package season4.painandgain

/**
 * НАСТРОЙКИ АРМИИ (v258, этап 10 переработки). Константы, которые читают несколько стадий конвейера или только
 * оркестровка тика: пороги паритета и силы, радиусы, окна историй, сроки, ключи печати. Константа, которую читает
 * одна стадия, лежит в файле этой стадии. Над каждой — её история и замеры, перенесённые из объекта PainAndGain
 * дословно; отвергнутые правила — в docs/pain-and-gain-verdicts.md.
 */

// ---------- боевые константы ----------
internal const val MELEE_KEEP_RANGE = 2

internal const val MELEE_KITE_DISCOUNT = 0.1

internal const val MELEE_ADJACENCY_SHARE = 0.25

/** ОТВЕРГНУТО (v195, см. inFront в planFight): мили вставал позади стрелков, когда по замеру не достаёт. Правило
 *  почти не срабатывало — прибор `back` дал 2 тика за матч, — потому что против СОМКНУТОГО блока строй раздаёт
 *  planBlock, а не planFight. И посылка неверна: в planBlock мили стоит в общей линии со стрелками НАМЕРЕННО, и
 *  рядом записан замер, который это держит, — строй «стрелки впереди, мили позади» (v37) кайтер стенда разоружал
 *  первыми. Живые числа согласны: гибнут только атакующие части (0–16 из 32), стрелковые целы (24–30 из 30), то
 *  есть тела мили работают самой дешёвой бронёй, какая у нас есть. Убирать броню, которая всё равно ничего не
 *  бьёт, — значит подставить под тот же огонь единственное, чем мы бьём. */

/** Перевес, при котором армия идёт добивать, и порог продолжения. Порог продолжения выше единицы: прежний
 *  0.9 вместе со входом «по контакту» открывал лазейку — контакт с ОДНИМ стрелком включал ДОБИТЬ, а дальше
 *  гистерезис держал его при 0.97, и армия прошла через всю карту к вражескому углу (матч 3, t=60–96). */
internal const val PUSH_RATIO = 1.3

/** Наступление окупается: за окно STALL_TICKS с врага снято не меньше, чем с нас (суммы хитов живых, лечение обеих сторон
 *  внутри), иначе наступление снимается и строй собирается заново. Матч 44 (けろびー v1): к 180-му мы выигрывали
 *  16000/16000 против 12800/12800, трое его мили мертвы, и при перевесе 1.3 армия пошла в наступление — строй распущен,
 *  крипы гнались поодиночке за линией стрелков, которая отошла на 18 клеток, стреляя из трёх: 311 его выстрелов против
 *  наших 175 (68 % крип-тиков с выстрелом против 44 %), r→melee 137 по идущим первыми мили — за 60 тиков размен
 *  перевернулся, армия потеряна. Ланчестер даёт право наступать, размен говорит, окупается ли оно. */
internal const val PUSH_EXCHANGE = 1.0

/** Проигрывая по прогнозу счёта, армия идёт добивать при меньшем перевесе: очки — у того, кто держит больше
 *  флагов, и он же слабее (дебаффы глобальны на сторону), а отсидеться — проиграть наверняка. Не при
 *  равенстве: оценка мощи шумит на ±5%, а прогноз счёта на 41-м тике («отстаём» на пять очков, пока скаут
 *  делает последний шаг к флагу) — не повод для решающего боя (стенд army). */
internal const val PUSH_RATIO_BEHIND = 1.1

/** Бесплодная охота (v20): в ДОБИТЬ без обмена уронами STALL_TICKS подряд давление, бой по контакту и «держим линию»
 *  снимаются на STALL_COOLDOWN тиков — армия идёт за флагами; любой удар в любую сторону снимает паузу. Враг россыпью
 *  (матч 19) разобрал все флаги по одному-трём крипам и держал +25 в тик, а наша армия при 1.34 стояла в ДОБИТЬ рядом
 *  с его крипами, висевшими в 4–6 клетках и отступавшими на клетку при каждом нашем шаге (равная скорость — ни одного
 *  удара за матч), и флагов не брала: ДОБИТЬ обнуляет цель. Гейт по дальности до цели («охота только вблизи») это не
 *  чинит — висящие в шести клетках «вблизи», а против армии, которая дерётся при подходе (стенд m3 army), он выключил
 *  давление вовсе, и обе армии простояли до конца. Критерий — результат, не дистанция. */
internal const val STALL_TICKS = 20

/** Ротация по его фокусу живёт по той модели его прицела, что выиграла сверку с фактом (v510, см. rotateByFocus), —
 *  тот же принцип, что v292 уже применила к ожидаемому входящему в той же функции (`focusPredDmg`). Прежде правило
 *  требовало победы модели «наименьшая доля» и при её проигрыше выключалось ЦЕЛИКОМ, а жертву брало из проигравшей
 *  карты. Восемь тестовых рук против MetalicaX#17 (21.09.2026): `hwwhy=addrModel` в семи из восьми, ротация мертва
 *  во всех семи; в единственной руке, где она ожила, экспозиция лекарей 18 % против 32-70 % и рука выиграна.
 *
 *  ⚠️ ЖИВОЙ A/B 16+16 против MetalicaX#17 (21.09.2026): ПРИБОР ПОДТВЕРДИЛ ПРАВКУ, ИСХОД НЕ СДВИНУЛСЯ. Ротация
 *  ожила ровно как задумано — `rotf` с ненулевым числителем в 16 руках из 16 у правки (от 2 до 70 ротаций за
 *  матч) против 5 из 16 у базы, где механизм был мёртв в одиннадцати. Счёт при этом 3-13 у правки против 4-12 у
 *  базы, то есть разница в одну игру — шум.
 *
 *  Тумблер ОСТАВЛЕН включённым, и это сознательно: правка не подгоняет меру, а снимает ПРОТИВОРЕЧИЕ — два
 *  правила о «кого он сейчас выстрелит» читали одну величину по разным моделям, причём ротация была прибита к
 *  проигравшей по построению и при её проигрыше выключалась целиком. Гейт 143 PASS. Но записано прямо: выигрыша
 *  в счёте она не дала, и ссылаться на неё как на рычаг нельзя. */
internal const val USE_ROT_BY_BEST_MODEL = true

/** Изъятие «лекарь входит в досягаемость его стрелков ради лечения» действует только при лечении ВПЛОТНУЮ (v511,
 *  см. Tactician, `carveNow`). Само изъятие обосновано арифметикой «72 за часть вплотную против 24 на дистанции»,
 *  но условие пускало лекаря в огонь и при подопечном в двух-четырёх клетках — а там он льёт ту же треть, что лил
 *  бы снаружи, то есть платит уроном за ноль.
 *
 *  Цена половины, снимаемой здесь, снята с реплеев четырёх поражений от MetalicaX#17 (21.09.2026): лекарь-тиков
 *  под его стволами с лечением ТОЛЬКО дальним или вовсе без лечения — 11-20 за матч при 110-284 полученного урона,
 *  и контрфакт «стоять вне огня и лечить дальним» даёт РОВНО ТО ЖЕ лечение (440/288/288/460 против фактических
 *  404/240/264/456). В двух поражениях из четырёх в этих тиках не лечили совсем. Безопасная клетка с подопечным в
 *  пределах трёх и вне всех его радиусов существовала в 44-100 % таких тиков и была достижима одним шагом в 30-87 %.
 *
 *  Половина «лечение вплотную» здесь НЕ трогается, хотя замер и её не оправдывает против этого соперника (добавка
 *  сверх дальнего варианта стоит 0,74-1,19 хита урона на хит лечения и списывает 15-23 HEAL-части за матч, тогда
 *  как в победах то же изъятие берётся 12-13 тиков и не стоит ни одной части): она обоснована отдельным живым
 *  замером (матч 34), и снимать её надо своей пробой, а не заодно.
 *
 *  ⚠️ ОТВЕРГНУТО СВОИМ ЖЕ ПРИБОРОМ (v512, живой A/B 16+16 против MetalicaX#17, 21.09.2026). Счёт 5-11 против
 *  5-11 — ровно одинаково, а экспозиция лекарей, ради которой правка и сделана, ВЫРОСЛА: `hexp` = 3164/5877 =
 *  53,8 % против 2327/6277 = 37,1 % у базы. Гейт при этом был чист (143 PASS) и обещал обратное (11,2 % против
 *  11,7 %, 45 сценариев лучше против 28 хуже) — ещё один случай, когда стенд по этой подсистеме не судья
 *  (его же строка экспозиции говорит «командир в бою 0,6 % ⚠️НИЗКО»).
 *
 *  Чтение отказа: запрет входить в досягаемость ради ДАЛЬНЕГО лечения не убирает лекаря из-под огня, а меняет
 *  клетку, с которой он туда попадает, — и попадает чаще. Значит дело не в том, ЗАЧЕМ лекарь входит, а в том, что
 *  его вообще достают: оператор (21.09.2026) называет проверку прямо — при верных эшелонах его стрелку, чтобы
 *  достать лекаря на 3, надо встать ВПЛОТНУЮ к нашим мили, где его рубят на 240 в тик; если достаёт не подходя,
 *  предмет в ПОСТРОЕНИИ, а не в поведении лекаря. Это и меряется следующим. */
internal const val USE_HEAL_CARVE_ADJACENT_ONLY = false

/** Изъятие «лекарь входит в досягаемость ради лечения» ТРЕБУЕТ ПЕРВОГО РЯДА (v513, см. Tactician, `carveNow`):
 *  когда у армии не осталось ни одной живой части ATTACK, прикрывать лекаря нечем, и он встаёт рядом с бойцом,
 *  который его не защищает.
 *
 *  Проверка оператора (21.09.2026): «при правильном построении, чтобы он смог стрелять по нашим лекарям, его
 *  рэнджи должны подойти на расстояние 3 и быть вплотную с нашими мили; если это не так — эшелоны неверны».
 *  Замер восьми реплеев подтвердил её целиком: из 566 событий «он выстрелил в нашего лекаря» он стоял >= 2 клеток
 *  от нашего ближайшего ЖИВОГО мили в 100 %, выстрелов с дистанции 1 — НОЛЬ, наших мили на линии выстрела не было
 *  ни разу (13 первых попаданий из 13).
 *
 *  И замер же сузил предмет: различает исходы не глубина рядов — зазор «мили → лекари» по оси на врага у нас
 *  −0,1 / 1,1 / 0,7 / −0,3 клетки в поражениях и −1,0…+1,7 в победах, то есть одинаково мелкий, тогда как у него
 *  1,8–3,5 во всех восьми, — а НАЛИЧИЕ ПЕРВОГО РЯДА ВООБЩЕ: событий «живого мили нет ни одного» 36 / 79 / 35 / 50 %
 *  в поражениях против 0 / 20 / 0 / 0 % в победах, а среди фактических выстрелов по нашим лекарям на такие тики
 *  приходится 61–93 %. Правила, отвечающего на это состояние, в боте не было ни одного.
 *
 *  Прибор — `hfront=` (отказано / раз, когда изъятие было бы взято).
 *
 *  ⚠️ ОТВЕРГНУТО КАК ИНЕРТНОЕ (v514, живой A/B 16+16 против MetalicaX#17, 21.09.2026), и отказ называет дефект
 *  ФОРМЫ, а не замысла. Счёт 4-12 против 4-12 — ровно одинаково, и это ничего не значит: прибор показал, что
 *  правка почти не срабатывает. `hfront=0/N` в пятнадцати руках из шестнадцати, отказ выдан РОВНО ОДИН РАЗ за всю
 *  серию (`hfront=1/2`).
 *
 *  Причина: запрет накладывается только на лекаря СНАРУЖИ досягаемости — `if (support && !inReach && …)`, — а
 *  измеренное состояние ровно обратное: 61-93 % выстрелов по нашим лекарям приходятся на тики, когда лекарь УЖЕ
 *  внутри и первого ряда уже нет. Набор избегаемых клеток такого крипа не трогает по построению; выталкивать его
 *  оттуда должна лестница бегства (`mustFlee` и ступень отхода), и правило «нет живого мили — лекарь выходит»
 *  надо ставить туда, своей пробой. */
internal const val USE_HEAL_CARVE_NEEDS_FRONT = false

/** Без первого ряда досягаемость для лекаря снова ПОЛНАЯ — со стрелками (v515, см. Tactician, `reachNow`).
 *
 *  Сужение до одних мили (v293/v294) стоит ради того, чтобы лекарь не бросал фронт: пока свои мили дерутся,
 *  лечить их надо вплотную. Но когда у армии не осталось НИ ОДНОЙ живой части ATTACK, фронта нет вовсе —
 *  бросать нечего, а лекарь стоит под его стрелками без прикрытия.
 *
 *  Ступень бегства для этого в лестнице УЖЕ есть — `supportInReach` в `mustFlee`; закрыт был только вход в неё,
 *  потому что `inReach` считается по набору, который в контакте про его стрелков не знает. Это и есть исправление
 *  дефекта формы, названного отказом v514: тот ставил правило в набор избегаемых клеток, который по построению не
 *  трогает крипа, УЖЕ стоящего внутри, — а измеренное состояние именно такое.
 *
 *  Замер восьми реплеев (21.09.2026, проверка оператора по эшелонам): из 566 событий «он выстрелил в нашего
 *  лекаря» он стоял >= 2 клеток от нашего ближайшего ЖИВОГО мили в 100 %, с дистанции 1 — НОЛЬ, наших мили на
 *  линии выстрела не было ни в одном из тринадцати первых попаданий. Разделяет исходы наличие первого ряда
 *  вообще: «живого мили нет ни одного» — 36/79/35/50 % тиков в поражениях против 0/20/0/0 % в победах, и на эти
 *  тики приходится 61-93 % всех выстрелов по нашим лекарям. Прибор состояния — `nofront=`.
 *
 *  ЖИВОЙ A/B 16+16 против MetalicaX#17 (21.09.2026): 3-13 у правки против 2-14 у базы — не хуже, но и не
 *  различение. Тумблер оставлен: правка открывает уже существующую ступень бегства в состоянии, где лекарь
 *  беззащитен по построению, и гейт чист (143 PASS).
 *
 *  ⚠️ НО ГЛАВНОЕ ДАЛ САМ ПРИБОР, И ЭТО САМОЕ РЕЗКОЕ ЧИСЛО ДНЯ. `nofront=` живьём: 174/296, 985/1100, 864/1000,
 *  194/300 — то есть **59-90 % тиков с живой армией у нас НЕТ НИ ОДНОЙ ЖИВОЙ ЧАСТИ ATTACK**; в одной руке
 *  `nofront=0/1300` при `hexp` 42/345. Знаменатель считает только тики, где стадия армии вообще звалась, то есть
 *  армия жива, — значит армия живёт без первого ряда большую часть боя. Тело `a8m8` несёт восемь ATTACK впереди
 *  (800 хитов из 1600), лечение чинит с хвоста, и чтобы вернуть первую же ударную часть, мили надо вылечить выше
 *  800. Предмет следующего захода — почему наши мили теряют ATTACK и не возвращают его, тогда как у него в
 *  победах происходит ровно обратное (его ATTACK уходит в ноль с t=64/83/77/87 и не отрастает). */
internal const val USE_REACH_FULL_WITHOUT_FRONT = true

/** ЛЕКАРЬ УХОДИТ ИЗ-ПОД ЕГО СТРЕЛКОВ ПО СВОЕЙ ПРИЧИНЕ (v518, см. TacticianState.healersOutOfReach и reachNow).
 *
 *  Дефект — один рычаг на два решения, и для одного из них он ПЕРЕВЁРНУТ. `huntsWounded` (v294) включает сразу две
 *  вещи: выход РАНЕНОГО из боя к лекарям позади и вывод ЛЕКАРЯ из досягаемости его стрелков. Условие у рычага одно —
 *  «выиграла модель наименьшей доли хитов». Для раненого довод v294 верен: если он не ищет раненых, уведённый из боя
 *  раненый есть огонь, потерянный даром. Для лекаря он противоположен: `huntsWounded = false` означает победу
 *  АДРЕСНОЙ модели, то есть «он бьёт лекаря, если тот в досягаемости, иначе ближайшего», — и ровно тогда бот
 *  оставлял лекаря под его стволами, сужая в контакте `reachNow` до клеток вплотную к его мили.
 *
 *  Числа 21.09.2026. Модель: `hwwhy=addrModel` в семи руках из восьми, а прямой замер по 35 реплеям — когда наш
 *  ВООРУЖЁННЫЙ лекарь стоял в его тройке, он выбирал именно лекаря в 61 % из 2523 случаев (мы в той же позиции —
 *  43 %). Разделение исходов: `hexp=` (лекарь в полной досягаемости) 9071/40235 = 22,5 % в 106 победах против
 *  59053/107648 = 54,9 % в 307 поражениях на несмещённой выборке логов серий; потери лечения `hlost` 667 против
 *  2378 за матч. По реплеям в окне 0..60 тиков боя — 41 % против 77 %, дистанция лекаря до ближайшего врага 6,1
 *  клетки в победах против 3,1 в аннигиляциях, под огнём 12 % тиков против 42 %.
 *
 *  Цена выхода — НОЛЬ, и это главное: лекарь на шести клетках доставляет ровно столько же, сколько на трёх. Раненых
 *  вплотную у него 1,24 против 1,27, в радиусе лечения 4,59 против 4,55. Контрфакт v511 считал то же по-другому и
 *  получил то же: «стоять вне огня и лечить дальним» даёт 440/288/288/460 против фактических 404/240/264/456.
 *  Арифметика арены: тело лекаря `h6m6` несёт шесть HEAL впереди (600 хитов из 1200), его залп по лекарю — пять
 *  стрелков по 60, то есть все шесть частей лечения уходят за два тика; 12 лечения в тик за часть не возвращаются
 *  ничем, пока лекарь не вылечен выше 600.
 *
 *  Одна строка закрывает и вход в зону, и выход из неё: `inReach` ступени бегства `supportInReach` считается по
 *  этому же набору `reachNow`, поэтому расширение набора включает обе половины. Прибор правки — `hor=`; вердикт
 *  читать по `hexp=`, а не по счёту (v516, поведенчески тождественная v515, дала 5-3 против её же 3-13 в тот же вечер).
 *
 *  ⚠️ ОТВЕРГНУТО СВОИМ ЖЕ ПРИБОРОМ, и это самый полезный отказ захода. Живой A/B против MetalicaX#17, 13 рук:
 *  база 3-4, правка 1-5, а главное — **`hexp` 75,1 % (5385/7169) у правки против 41,9 % (991/2367) у базы** при
 *  `hor=4499/5200 = 86,5 %`, то есть правило исправно срабатывало и сделало свою же цель ВДВОЕ ХУЖЕ. Живых в конце
 *  3,2 против 5,9, очки 29065:75884 против 70738:27810.
 *
 *  ПРИЧИНА — арифметика движка, и она закрывает целый класс правок. Тела арены (`a8m8`, `r6m6`, `h6m6`) несут MOVE
 *  ровно в половину тела: усталость за шаг по равнине у всех покрывается, то есть КАЖДЫЙ крип ходит 1 клетку в тик,
 *  включая преследователя. Значит бегство одного крипа от вооружённого врага НЕ УВЕЛИЧИВАЕТ ДИСТАНЦИЮ вовсе — оно
 *  только рвёт строй, уводит от своих лекарей и теряет цель. Лекарь, выгнанный из зоны ступенью бегства, из неё не
 *  выходит: он мечется внутри, лишившись прикрытия, и оказывается в ней ЧАЩЕ. То же говорит прибор `fled=`
 *  (приказов, перебитых бегством): 83 за матч в поражениях против 15 в победах при впятеро более коротких
 *  поражениях, то есть на тик в двадцать пять раз больше; рядом `obey` 84 % против 97 % и `breakoff` 44 % против 10 %.
 *
 *  ЧТО ИЗ ЭТОГО СЛЕДУЕТ ДЛЯ СЛЕДУЮЩЕЙ ПОПЫТКИ. Задача «лекарь вне досягаемости» верна (замеры в теле этого KDoc
 *  никуда не делись), но решается она НЕ бегством крипа, а ФОРМОЙ АРМИИ: эшелон, в котором клетки лекарей лежат за
 *  пределами его дальности по построению. Уводить крипа из зоны по одному — в этой арене невозможно. */
internal const val USE_HEALERS_OUT_OF_REACH = false

/** УХОД ЛЕКАРЯ ИЗ-ПОД ОГНЯ ОБЯЗАН ОКУПАТЬСЯ (v519, см. `fleeHopeless` и ступень `supportInReach` в `mustFlee`).
 *
 *  Прямое следствие отказа v518 и первая правка захода, опирающаяся на арифметику ДВИЖЕНИЯ, а не огня. Тела арены
 *  (`a8m8`, `r6m6`, `h6m6`) несут MOVE ровно в половину тела: усталость за шаг по равнине покрывается у всех, то есть
 *  каждый крип ходит одну клетку в тик — преследователь тоже. Значит бегущий крип дистанции НЕ НАБИРАЕТ. Для лекаря
 *  это решает размен без всякой серии: стоя вплотную к подопечному он доставляет 72 лечения в тик, убегая — НОЛЬ
 *  (`fleeStep` уводит от врага, а подопечные у врага), а входящий у него в обоих случаях один и тот же.
 *
 *  Прибор назвал цену раньше правки. `hstep=` по свежим рукам против MetalicaX#17: в поражениях лекаря ведёт бегство
 *  в 35-50 % шагов (flee 192/239/428 из 553/666/864), в победах — в 0,1-0,3 % (flee 3/5/11 из ~3300-3900). Рядом
 *  `lay=`: в поражениях строя нет (`FREE:54,ROWS:11`, `FREE:62,ROWS:19`, `FREE:27,ROWS:12`), в победах он есть
 *  (`ROWS:41,FREE:36`, `ROWS:14,FREE:1`, `ROWS:18,FREE:2`) — бегство и есть то, что строй разбирает. На всей
 *  несмещённой выборке логов то же самое видно по `fled=` (приказов, перебитых бегством): 83 за матч в поражениях
 *  против 15 в победах при впятеро более коротких поражениях, `obey` 84 % против 97 %, `breakoff` 44 % против 10 %.
 *
 *  ФОРМА ПРАВКИ НАЙДЕНА ГЕЙТОМ, В ТРИ ЗАХОДА, И ЭТО ЧАСТЬ ВЕРДИКТА. (1) «Лекарь с раненым подопечным не бежит
 *  вовсе» уронило `match13:brawl+heals` из 4842:822 в 14316:15098; то же и при сужении до лечения ВПЛОТНУЮ.
 *  (2) «Бежать некуда» (ни одной клетки шага вне его досягаемости после его же шага) гейт тоже не принял — в том
 *  сценарии условие давало 160/538 = 30 % тиков, а уйти там на самом деле есть куда: бинарная проверка «в зоне или
 *  нет» слепа к тому, что на краю зоны достаёт один ствол вместо трёх. (3) Принято сравнение В ТЕХ ЖЕ ЕДИНИЦАХ:
 *  оставшись, лекарь доставляет 72 вплотную (24 в двух-трёх клетках); уйдя, доставляет ноль и снижает входящий на
 *  `here − best`. Уход окупается, только когда снятого урона больше несделанного лечения — из-под одного стрелка
 *  снимается 60 и 72 не окупает, из-под двух 120 и окупает. Гейт 143 PASS, экспозиция на стенде 8,1 %
 *  (190610/2357826), в разбитом прежде сценарии 1,7 %.
 *
 *  Граница правки: только лекарь и только когда подопечный есть и ранен. Ступень `supportAloneNearFoe` (рядом нет
 *  ни одного своего) не трогается — там лечить некого; раздетый боец не трогается — он не доставляет ничего, и его
 *  уход из-под огня ничего не стоит. Прибор правки — `fuse=`; вердикт по нему и по `hstep=flee`, а не по счёту.
 *
 *  ⚠️ ОТВЕРГНУТО, И ПРЕЖДЕ ВСЕГО ПОТОМУ, ЧТО АРИФМЕТИКА ВЫШЕ НЕПОЛНА. Она сравнивает РАЗОВЫЕ величины: 72 лечения
 *  против снятого за тик урона. Но урон по лекарю снимает его части HEAL, а часть — это 12 лечения в тик НАВСЕГДА,
 *  пока её не вылечат обратно выше порога 600. При горизонте даже в 30 тиков уход из-под одного стрелка стоит
 *  0,6 части × 12 × 30 ≈ 216 лечения против 72 несделанных — то есть уход окупается почти всегда, и правило,
 *  которое его запрещает, вредно по построению. Правильная форма сравнения — поток, а не разовая величина.
 *
 *  Живой A/B против MetalicaX#17, 10 рук: 2-3 против 2-3 по счёту, но живых в конце 4,0 против 5,8, `hexp` 64,2 %
 *  против 28,8 %, а прибор цели пошёл В ПРОТИВОПОЛОЖНУЮ СТОРОНУ — `hstep=flee` 22,2 % у правки против 2,6 % у базы
 *  при `fuse=1531/5114 = 29,9 %` (правило исправно срабатывало). Механика понятна: задержанный в зоне лекарь из неё
 *  не выходит, а дёргается внутри — на следующем тике он снова `inReach`, и часть этих проверок уже разрешает уход.
 *
 *  ЧТО ЭТИ ДВА ОТКАЗА (v518 и v519) УСТАНОВИЛИ ВМЕСТЕ. Бегство лекаря — не дефект, а СИМПТОМ: ни запретить его, ни
 *  усилить нельзя с пользой, потому что решается не оно. Лекарь не должен ПОПАДАТЬ в досягаемость его стрелков, и
 *  это свойство ПОСТРОЕНИЯ АРМИИ, а не поведения одного крипа. Следующие попытки — туда. */
internal const val USE_HEALER_STANDS = false

/** ОГОНЬ ПО ЛЕКАРЮ СТОИТ ПОТОКА ЛЕЧЕНИЯ, А НЕ ОДНОГО ТИКА (v520, см. HEALER_W_FLOW в Tactician).
 *
 *  Третий случай одного класса дефекта после v506 и v510: ДВЕ ветки, ведущие лекаря, читают одну величину по
 *  разным правилам. В цене клетки от командира опасность идёт с весом `W_DAN = 1,0` (`Deal.scoreHeal`), в
 *  свободном шаге тактика — с весом `HEALER_W_DAMAGE_FIGHT = 0,02`, в пятьдесят раз меньше; а по прибору `hstep=`
 *  свободный шаг ведёт лекаря в 42 % случаев.
 *
 *  Арифметику назвал сам код и сам же её не применил: «каждые 100 урона это −12 лечения в тик до конца матча,
 *  замены нет» (комментарий к HEALER_W_DAMAGE), после чего вес поставлен такой, будто потеря частей разовая.
 *  Вывод веса — в KDoc HEALER_FLOW_TICKS: единица шкалы оценки клетки ≈ 4,8 лечения, сто урона стоит 12 лечения в
 *  тик на весь остаток, за горизонт 10 тиков это 120 лечения = 25 единиц, то есть 0,25 за единицу урона. Прежние
 *  0,02 и 0,05 соответствуют горизонту меньше одного тика.
 *
 *  Замер, ради которого правка делается (21.09.2026, 26 реплеев, окно 0..60 тиков боя). Глубина нашего строя —
 *  зазор от мили до лекарей — около ОДНОЙ клетки, у него 1,8-3,5. Средняя дистанция до ближайшего вооружённого
 *  врага у нас в аннигиляциях: мили 2,48, стрелок 2,91, лекарь 3,45 (под огнём 42 % тиков в окне 21..60); в
 *  победах: мили 4,45, стрелок 5,10, лекарь 5,94-6,51 (под огнём 12 %). Лекарь стоит почти в одной линии с
 *  фронтом, и это цена клетки его туда и ставит: доставка вплотную 72 против 24 с трёх, а риск не взвешен.
 *  Сам комментарий к весу называет это открытой находкой: «строй лекарей вне досягаемости стрелков».
 *
 *  ✅ ПРИНЯТО ЖИВЬЁМ — первая правка за сорок версий, сдвинувшая уровень. A/B против MetalicaX#17, 15 рук на
 *  сторону (серия остановлена на 30 из 32), чередование A/B/A/B:
 *
 *  | | база | v520 |
 *  |---|---|---|
 *  | счёт | 3-12 (20 %) | **6-9 (40 %)** |
 *  | `hexp` — лекарь в зоне досягаемости | 64,3 % | **36,3 %** |
 *  | `hstep=flee` — лекаря ведёт бегство | 31,3 % | **3,7 %** |
 *  | живых в конце | 3,3 | **5,1** |
 *  | очки | 70335 : 113790 | **130907 : 36285** |
 *
 *  ⚠️ И главное в этих числах — НЕ счёт, а то, как повело себя бегство. Его никто не трогал: `USE_HEALER_STANDS`
 *  выключен, ступень `supportInReach` та же. Бегство лекаря упало с 31,3 % до 3,7 % САМО, потому что лекарь
 *  перестал входить в зону. Это и есть подтверждение вывода из отказов v518/v519: бегство было симптомом, и
 *  лечится оно ценой клетки, а не правилом о бегстве. */
internal const val USE_HEALER_DANGER_FLOW = true

/** СТРЕЛОК ДЕРЖИТ ТРИ, ПОКА У СОМКНУТОГО ВРАГА ЖИВ МИЛИ (v521, см. `closeIn` в Tactician).
 *
 *  Четвёртый случай класса «правило измеряется, но не действует». Правило записано решением оператора в v220 —
 *  «мы принимаем бой, когда у нас впереди рэнжи, в которых его мили сразу врезаются на первом тике», — его
 *  условие вычислено в `foeMeleeLive` (его мили жив И его армия сомкнута), а `closeIn` этой величины НЕ
 *  СПРАШИВАЕТ: она уходит только в прибор `close3`. Правило существовало как комментарий и счётчик.
 *
 *  Арифметика, записанная там же и не применённая: `CLOSE_STANDOFF = 2` — ровно та клетка, с которой ЕГО мили
 *  делает ОДИН шаг и бьёт на 240; с трёх ему нужно два шага, а наш выстрел достаёт и оттуда (`RANGED_RANGE = 3`).
 *  То есть сближение с трёх до двух не покупает нам НИ ОДНОГО очка урона и дарит ему темп. В потоке (см.
 *  USE_HEALER_DANGER_FLOW) это ещё хуже: 240 урона по `r6m6` — это 2,4 части RANGED_ATTACK, то есть 24 урона в
 *  тик, потерянных до конца матча.
 *
 *  Прибор правила делит исходы резче почти всего в своде: `close3` (доля агрессивных тиков стрелка, пришедшихся
 *  на живого мили сомкнутого врага) — **27,2 % в 316 поражениях против 2,1 % в 108 победах** на несмещённой
 *  выборке логов серий. Замер по реплеям подтверждает ту же геометрию: наши стрелки стоят в 2,91 клетки от
 *  ближайшего вооружённого врага в аннигиляциях против 5,10 в победах.
 *
 *  Сужение до сомкнутого врага уже в `foeMeleeLive` и оно не моё: первая редакция v220 спрашивала про любого
 *  живого мили рядом и уронила `match28:scatter` (24310:13503 -> 21781:24307), потому что против РАССЫПАННОГО
 *  соперника «держать три» значит не догнать никого. */
internal const val USE_HOLD_THREE_VS_MELEE = true

/** КЛЕТКА ОТХОДА НЕ ПЕРЕПИСЫВАЕТСЯ БОЕВОЙ РАСКЛАДКОЙ (v522, см. passMelee / passRanged / passStripped в Deal).
 *
 *  Дефект механический и виден по списку проходов: `passStraggler`, `passKeeper` и `passCatchall` начинаются с
 *  `if (c.id in out) continue`, а `passMelee`, `passRanged` и `passStripped` — нет. Проход отхода (`passRetreat`)
 *  идёт ПЕРВЫМ и выдаёт раненому, одинокому и ротирующемуся клетку по своему правилу — с единственным во всей
 *  раздаче слагаемым «ближе к медику» (v407/v408). Следующие три прохода выдают тем же крипам другую клетку по
 *  обычной боевой оценке, и правило «идти к лекарю» исчезает бесследно.
 *
 *  Цена названа приборами самого бота: за матч против MetalicaX#17 `sout=0/0/0` (выход раненого не сработал ни
 *  разу), `meet=0/0/0/0/0` (точка встречи с лекарем не создана ни разу), `rotset=0/434` (ротация по его фокусу
 *  мертва), при `rot=12`. Побочно `rotatingMeet` хранит уже брошенную клетку, и отдельный проход `meetWounded`
 *  ведёт ЛЕКАРЯ встречать раненого туда, где того не будет.
 *
 *  Почему это важно именно сейчас: замер 21.09.2026 показал, что наш раздетый боец стоит в 4,04 клетки от
 *  собственного лекаря (у соперника 1,99) и возвращает оружие за пять тиков в 10 % случаев против его 35 %, а
 *  лечение вплотную даёт 72 в тик против 24 с трёх и нуля с четырёх. Механизм, который должен это чинить, в коде
 *  есть с v276 и v407 — он просто не доживает до исполнения.
 *
 *  Прибор правки — `repass=` (сколько раз клетка отхода сохранена из всех проходов боевой раскладки).
 *
 *  ➖ ЖИВЬЁМ НЕ РАЗЛИЧИМА, и это честный вердикт, а не победа. A/B против MetalicaX#17, 19 рук: 3-6 (33 %) против
 *  3-7 (30 %) у базы, `hexp` 41,7 % против 42,4 %, живых 3,3 против 3,5 — всё внутри шума при работающем приборе
 *  (`repass=236/1681 = 14,0 %`). Тумблер оставлен включённым: правка устраняет механическую несогласованность
 *  (три прохода теперь ведут себя как остальные три, у которых проверка есть с самого начала) и ничего не ломает.
 *
 *  ⚠️ И вывод, который из этого следует для мёртвой ротации: дело НЕ только в перезаписи клетки. Раз сохранение
 *  клетки отхода исхода не двигает, значит правило «идти к лекарю» надо чинить не запретом на переразмещение, а
 *  слагаемым медика ВНУТРИ боевой оценки — там, где крип и получает клетку в подавляющем большинстве тиков. */
internal const val USE_RETREAT_CELL_STICKS = true

/** ПРИКАЗ ЛЕЧЕНИЯ ДЕЙСТВУЕТ И ВПЛОТНУЮ (v523, см. healAndShoot в Fight).
 *
 *  Пятый случай класса «правило записано, но действует не там». v183 (решение оператора: «не должно быть ничего,
 *  что идёт мимо командира») обещает в самом коде: «ПРИКАЗ ДЕЙСТВУЕТ НА ВСЕЙ ЛЕЧЕБНОЙ ДАЛЬНОСТИ… прежде назначенный
 *  пациент брался, только если он ВПЛОТНУЮ». Исполнено зеркально: `ordered` спрашивает ТОЛЬКО дальняя ветка, а
 *  ближняя выбирает соседа в одной клетке местным рангом и выходит по `continue`, до дальней не доходя. То есть
 *  приказ работает ровно пока пациент НЕ вплотную — и отбрасывается тем, что рядом просто кто-то стоит, о чём
 *  комментарий и предупреждает.
 *
 *  Почему приказ важнее местного ранга: `commandHeal` назначает пациента, зная, кого добивают в этот тик и кого
 *  лечение спасёт (умирающий и спасаемый первыми, затем — чья оружейная часть вернётся, v496), и распределяет
 *  лекарей между целями, чтобы не лить троих в одного. Местный ранг соседа не знает ни очерёдности, ни того, что
 *  делают другие лекари. Цена ошибки — разница между 72 лечения вплотную и 24 с трёх, отданная не тому.
 *
 *  Прибор правки — `heord=` (сколько раз приказ взят вплотную из всех тиков, где ближняя ветка вообще выбирала).
 *
 *  ✅ ПРИНЯТО ЖИВЬЁМ вместе с USE_LETHAL_SAME_RULE. A/B против MetalicaX#17, 14-15 рук на сторону (серия
 *  остановлена на 29 из 32): счёт **6-8 (43 %) против 4-11 (27 %)** у базы, `hexp` 45,4 % против 49,5 %, живых в
 *  конце 6,4 против 4,2, очки 129525:52491 против 74445:32340. Прибор правки `heord=931/2270 = 41,0 %` — то есть
 *  в 41 % выборов ближней ветки лекарь теперь исполняет приказ вместо местного ранга. */
internal const val USE_HEAL_ORDER_ADJACENT = true

/** СМЕРТЕЛЬНОСТЬ КЛЕТКИ — ОДНО ПРАВИЛО НА ДВЕ ВЕТКИ (v524, см. `lethal` в Deal и `lethalNow` в Tactician).
 *
 *  Шестой случай класса «одна величина — два правила». Вето командира (`Deal.lethal`, v178) считает ВАЛОВОЙ
 *  входящий за ОДИН тик: `danOf(c, key) >= c.hits`. Оценка клетки у тактика (`lethalNow`, v215) считает ЧИСТЫЙ,
 *  за вычетом нашего лечения, за ДВА тика: `netDamageAt(...) * 2 >= hits`. Обе ведут ОДНОГО крипа в ОДНОМ тике.
 *
 *  Довод в пользу чистого записан у тактика и полностью применим к командиру: штампованное поле не знает про наше
 *  лечение, и клетка рядом с тремя живыми лекарями объявляется смертельной, хотя входящий там перекрыт с запасом
 *  (три лекаря вплотную дают 216 в тик). Пока лекари живы, расхождение постоянное, и оно бьёт ровно по той
 *  клетке, которая нам нужна, — по клетке ЗА своим строем, рядом с лечением.
 *
 *  Два тика вместо одного — тоже от тактика: крип, шагнувший в клетку, проведёт там не меньше двух тиков (шаг
 *  туда и шаг обратно), и однотиковая мерка систематически недооценивает цену входа.
 *
 *  ✅ ПРИНЯТО ЖИВЬЁМ в паре с USE_HEAL_ORDER_ADJACENT (числа — в KDoc того тумблера): 43 % против 27 % у базы на
 *  14-15 руках. Раздельного вердикта у двух правок нет: они проверялись одной пачкой, потому что обе механические,
 *  обе одного класса и обе в решении «где стоять и кого лечить». Если понадобится развести — у каждой свой
 *  тумблер и свой прибор (`heord=` и доля клеток под вето). */
internal const val USE_LETHAL_SAME_RULE = true

/** ДОБИВАЕМОСТЬ ЗА ТИК — ОДНО ПРАВИЛО НА ВСЕ ТРИ МЕСТА (v525, см. `killableNowAt` в Tactician и `focusDying` в Fight).
 *
 *  Седьмой случай класса и самый влиятельный из найденных: одну величину — «умрёт ли он в этот тик» — считали три
 *  ветки по трём разным формулам, и все три решают ОГОНЬ ВСЕЙ АРМИИ.
 *
 *  - Приказ командира `commandFire.killable`: `burst >= hits + healCoverOn(...)` — залп достающих с множителем
 *    полученного урона МИНУС лечение, которое цель получит.
 *  - Верхний ярус сравнения фокуса и сброс липкости (`focusCmp`, `killableNow`): `hits <= burst` — лечение не
 *    вычитается вовсе.
 *  - Исключение мили «добиваю — не слушаю приказ» (`strike.focusDying`): `hits <= profileOf(creep).melee` — только
 *    свой удар, без множителя `takenOf` и без лечения.
 *
 *  Расхождение постоянное, пока у него жив хоть один лекарь: три лекаря вплотную дают 216 в тик, вплотную полное и
 *  треть на дистанции. Цель, «добиваемая» по голым хитам, переживает залп — и тогда фокус ставит её наверх, огонь
 *  армии уходит в неё, а мили ради неё ещё и нарушает приказ. Это прямо бьёт по концентрации, а против ёмкости
 *  лечения 216 в тик именно концентрация и решает: один наш мили даёт 240 и пробивает её, размазанный залп — нет.
 *
 *  Правило берётся то, которое считает полностью, — командирское. Новых величин не заводится: `healCoverOn` и
 *  `takenOf` уже есть и уже так используются.
 *
 *  ➖ ЖИВОЙ ЗАМЕР НЕПОЛОН: серия оборвана на 14 руках не по существу — страница клиента отдала `TypeError: Failed
 *  to fetch`, а при перезапуске сервер арены отвечал HTML вместо JSON. На сыгранном счёт РОВНЫЙ (2-5 против 2-5),
 *  побочные приборы у правки лучше: `hexp` 40,3 % против 49,0 %, `rnear` 6,8 % против 15,9 %. Тумблер оставлен
 *  включённым: правка механическая и устраняет расхождение, которого не должно быть ни при каком исходе, гейт
 *  143 PASS. При возможности — добрать серию и судить по концентрации огня (`conc=`, `okill=`), а не по счёту. */
internal const val USE_KILLABLE_SAME_RULE = true

/** МЕСТНЫЙ ПЕРЕВЕС ОТКРЫВАЕТ БРОСОК ТОЛЬКО НА ДОБИВАЕМОГО (v526, см. `covered` и `spotNow` в Tactician).
 *
 *  Восьмой случай класса. Одни и те же ворота — «у цели есть местный перевес по стволам» (`spotEdgeAt(e) >=
 *  PUSH_RATIO`) — стоят в двух местах, решающих одно: пойдёт ли наш мили в контакт. В `spotNow` рядом с ними
 *  спрошена ДОБИВАЕМОСТЬ (`killTicks(e)` конечен) и записан довод: «очаг у трёх его лекарей — не очаг». В
 *  `covered` тех же ворот эта проверка отсутствует.
 *
 *  Арифметика входа, из-за которой довод так весом. Наш `a8m8` несёт восемь ATTACK ВПЕРЕДИ тела — 800 хитов из
 *  1600. Войдя вплотную к сомкнутому блоку, он получает от всего, что достаёт: до четырёх его мили по 240 и пяти
 *  стрелков по 60, то есть порядка 1260 в тик, и теряет ВСЕ восемь ударных частей за один тик, успев нанести 240
 *  по одному. Размен в его пользу втрое. Он оправдан только если цель от этого умирает; если её лечат быстрее,
 *  чем мы бьём (три лекаря вплотную — 216 в тик), мы платим восемью частями ни за что.
 *
 *  Новых величин не заводится: `killTicks` уже считается и уже так используется в соседних воротах.
 *
 *  ⚠️ ОТВЕРГНУТО ГЕЙТОМ, дважды и в обе стороны. Широкая редакция уронила `match30:scatter` (20875:24278 там, где
 *  база выигрывает): против РОССЫПИ добиваемость почти всегда бесконечна — цель уходит, — и требование запирает
 *  преследование ровно там, где догонять и надо. Сужение до СОМКНУТОГО врага (`enemyMassedNow`, признак v220)
 *  перенесло падение на `match30:camp` — 17143:23630: лагерь сомкнут и нелечимо-живуч, но именно его надо
 *  давить, иначе он забирает очки.
 *
 *  Что это говорит о самом доводе. «Очаг у трёх лекарей — не очаг» верно для БРОСКА ОДИНОЧКИ (за него платят
 *  восемью частями ATTACK), но ворота `covered` открывают не только бросок — через них идёт и давление всей
 *  линией, у которого цена входа другая и окупается очками, а не убийством. Одно и то же условие обслуживает два
 *  разных решения; выравнивать надо было не условие, а РАЗДЕЛИТЬ решения. Это записано как открытый предмет, а не
 *  как ограничение: пока два решения делят одни ворота, любое их уточнение будет ломать одно ради другого. */
internal const val USE_COVER_NEEDS_KILLABLE = false

/** Раздетый БОЕЦ не получает скидку нужды (v517, см. InfluenceMap, `NEED_DISARMED`): вернуть оружие мили ценнее
 *  любой другой доставки в армии — он даёт 240 урона в тик против 60 у стрелка и 72 лечения у лекаря.
 *
 *  Скидка 0,35 пришла общим коммитом полей 10.09.2026 и НИ РАЗУ НЕ СУДИЛАСЬ: ни абзаца истории, ни записи в
 *  архиве вердиктов. Замер восьми реплеев (21.09.2026) говорит, что она бьёт по самому больному: падение мили
 *  ниже 800 хитов (восемь ATTACK впереди из 1600) случается одинаково в победах и поражениях, и во всех восьми
 *  матчах первым до нуля доходит ОН, на 3-67 тиков раньше нас, — а различает исходы ВОЗВРАТ частей. Навсегда без
 *  оружия остаются 0/2/0/0 наших мили из четырёх в победах против 4/4/4/4 в поражениях; разоружены они 0-10 %
 *  времени против 29-42 %; и в 97-100 % тиков разоружённого рядом стоит лекарь против 21-37 % тиков, где рядом
 *  нет НИ ОДНОГО. Петля замыкается сама: его мили раздевает наш УДАР (50-78 % урона), поэтому пока наши без
 *  оружия, снимать с него ATTACK нечем.
 *
 *  Место правки проверено прибором `hstep=` (v516), как велел оператор: в решающем тике клетку лекаря задаёт
 *  приказ командира в 56 % предложений (`order:168` против `free:123` и `flee:9`), то есть именно эта цена, а не
 *  лестница бегства, куда я ошибочно ставил v513 и v515.
 *
 *  Скидка остаётся тому, кому возвращать нечего, — крипу, рождённому без оружия. Прибор правки — `nofront=`
 *  (тиков без единой живой части ATTACK во всей армии): в победах 0 %, в поражениях 35-90 %.
 *
 *  ⚠️ ВЕРДИКТ НЕПОЛНЫЙ (21.09.2026): A/B 16+16 против MetalicaX#17 остановлен оператором на 10 руках у базы и
 *  9 у правки. На сыгранном — счёт 5-5 у базы против 3-6 у правки, и прибор НЕ СДВИНУЛСЯ: `nofront` суммарно
 *  816/7098 = 11,5 % у базы против 834/7326 = 11,4 % у правки. То есть на этих руках скидка нужды состояние
 *  «нет первого ряда» не изменила. Тумблер оставлен включённым до полной серии; при повторе судить по `nofront=`,
 *  а не по счёту — в тот же вечер v516, поведенчески тождественная v515, дала 5-3 против её же 3-13.
 *
 *  ⚠️ И оговорка к самому прибору: `nofront` делит исходы идеально (в победах 0-5 %, в поражениях 1-73 % в ОБЕИХ
 *  руках A/B), а значит к нему применимо правило «разделитель — не рычаг»: если мили мертвы или раздеты, бой уже
 *  проигран. Как вердикт правки он годится (двигает ли она состояние), как цель — нет. */
internal const val USE_NEED_DISARMED_FIGHTER = true

