 *  тогда `victimSaveable` ложно, `wallCellOf` чистится, и лекари возвращаются к общей цене клетки — а та насыщена
 *  (`min(нужда, 72)` = 72 у всякого, кто недобрал 72 хита) и подопечного не различает вовсе. Замер `hwall=` живьём
 *  против MetalicaX#17 (20.09.2026, четыре руки): 128/271, 44/118, 51/111, 14/82 — жертва есть, но не удержима в
 *  53–83 % таких тиков. Число из комментария самого правила говорит то же: клетка вплотную есть у Coldkimchi#1 в
 *  83–89 % тиков, в блобе MetalicaX#9 — в 29 %.
 *  Игра даёт третий вариант, которым правило не пользуется: `rangedHeal` с дистанции до HEAL_RANGE доставляет треть
 *  лечения, и `scoreHeal` эту треть в ветке стены УЖЕ считает (`d <= HEAL_RANGE -> deliver / 3.0`) — не хватает
 *  только клеток. Правка: когда безопасной клетки вплотную нет, стена берёт безопасные клетки в дальности лечения,
 *  а «удержимость» считается по трети, которую они дают. Форма отличается от трёх отвергнутых живьём 20.09 (v483,
 *  v484 — цена выстрела; v491 — кулак на всякий шаг): те расширяли ПРИНУЖДЕНИЕ, эта расширяет ОБЛАСТЬ ОПРЕДЕЛЕНИЯ
 *  уже принятого правила, оставляя его условия на месте. */
internal const val USE_HEAL_WALL_REACH = true

/** ЛЕКАРЬ ВЫБИРАЕТ ПОДОПЕЧНОГО ПО ОГНЕВОЙ МОЩИ, КОТОРУЮ ВЕРНЁТ ЕМУ ЛЕЧЕНИЕ (v496, см. `restoredPower`). Цена клетки
 *  лекаря — «лучшая одна доставка», `min(непокрытая нужда, лечение x ядро)`. В контакте нужда почти у всех больше
 *  потолка доставки (72 у h6), поэтому слагаемое выдаёт РОВНО 72 и вплотную к раненому мили, и вплотную к
 *  расстреливаемому стрелку: между подопечными оно не различает вовсе, и выбор делают опасность, влияние и «стой»,
 *  которые про подопечного не знают ничего. Отсюда измеренный разрыв `rhadj=` (v494): лекарь мог дотянуться до
 *  теряющего хиты стрелка в 89-97 % назначений, а вставал к нему в 20-34 %.
 *  ЧЕМ РАНЖИРОВАТЬ — назвал замер 16 рук против MetalicaX#17 (20.09.2026). На t=50 у нас `guns=5/5` и в победах, и в
 *  поражениях. На t=60 в ОБЕИХ победах знаменатель остаётся 5, а во ВСЕХ ТРЁХ поражениях падает 5 -> 4 при
 *  неизменном `hitsMax`: никто не погиб, а один наш стрелок за десять тиков контакта лишился всех шести стрелковых
 *  частей. Это 600 хитов направленного урона, а три наших лекаря за те же десять тиков доставляют 2 160 — лечения
 *  втрое больше, чем нужно, и оно не доходит. Дальше работает обратная связь: в победах `guns` идёт 3/3 -> 2/4 ->
 *  4/5 (крипы ВОЗВРАЩАЮТ себе оружие лечением), в поражениях только вниз 5 -> 4 -> 3 -> 2 -> 1.
 *  Правка берёт величину, которая у бота уже описана, но ценой клетки не читается: `potentialOf` - `profileOf` есть
 *  «мощь, выключенная уроном и возвращаемая лечением». Ранг подопечного — прирост ОРУЖЕЙНЫХ частей от доставки;
 *  сама величина остаётся в хитах, поэтому против опасности и влияния взвешивается ровно то же, что и раньше.
 *  Когда включить обратно нечего никому, выбор прежний, по хитам, — то есть правка тождественна вне своего предмета.
 *  ⚠️ Это НЕ «дать стрелкам вес» (ярлык роли, который я отказался писать в v494): мили под фокусом получает тот же
 *  ранг, и по мощи одной части он даже дороже (30 против 10). Роль в правиле не участвует.
 *  ⚠️ ПЕРВАЯ РЕДАКЦИЯ ОТВЕРГНУТА СВОИМ ЖЕ ПРИБОРОМ (v496 -> v497). Ключом была одна «возвращённая мощь», и живьём
 *  первая же рука дала `hdead=1860/4392` = 42 % — полоса проигравшего, как и до правки. Причина в самой формуле:
 *  мощь равна НУЛЮ и у целого крипа (возвращать нечего), и у глубоко раздетого (доставка до оружия не дотянет), а
 *  тай-брейком остаётся прежний недобор хитов — из двух нулей он снова выбирает раздетого, то есть ровно тот выбор,
 *  который правка отменяет. Ключ сделан трёхступенчатым (`weaponRank`): 2 — доставка включает часть обратно,
 *  1 — оружие ещё живо и его надо беречь, 0 — крип уже безоружен. */
internal const val USE_HEAL_BY_FIREPOWER = true

/** ПОДОПЕЧНЫЙ ЛЕКАРЯ — ПО СОХРАНЁННОМУ ВЫХОДУ, А НЕ ПО РАНЕ (v527, продолжение v496 на ШАГ лекаря).
 *
 *  1. Где стояло. `weaponRank` (v496) решает, кому лить лечение, когда лекарь УЖЕ стоит. А куда он идёт, решал
 *  `healMate` — `near.maxByOrNull { it.hitsMax - it.hits }`, то есть САМЫЙ РАНЕНЫЙ рядом. Это две разные величины в
 *  одном решении: лекарь идёт к одному, а льёт в другого, и доставка вплотную (72 за тик) достаётся тому, к кому он
 *  пришёл, а не тому, кто её стоит.
 *
 *  2. Арифметика. Армии в этой арене одинаковы: 4 мили `a8m8`, 5 стрелков `r6m6`, 3 лекаря `h6m6`. Самый раненый в
 *  бою — всегда мили: он стоит вплотную и принимает 240 за удар. Но восстановленная часть ATTACK работает, только
 *  пока мили смежен с врагом, а это 20-22 % тиков; часть RANGED работает на дистанции до 3, то есть 51-83 % тиков.
 *  На сто хитов лечения это 30 x 0,20 = 6,0 у мили против 10 x 0,74 = 7,4 у стрелка. И главное — переход через порог
 *  необратим: у `r6m6` порог 600, ниже него лечение чинит MOVE, и вернуть оружие стоит сначала 600 впустую.
 *
 *  3. Замер (26 реплеев против MetalicaX#17, 21.09.2026, окно 0-20 тиков боя). Доля лечения по ролям: у нас мили
 *  52 %, стрелок 34 %; у него мили 33 %, стрелок 58 %. Чистая убыль за тик (полученный урон минус лечение): наши
 *  стрелки -60, его -17; наши мили -112, его -224. Он РАЗМЕНИВАЕТ мили и БЕРЕЖЁТ стрелков — и к тикам 21-60 у него
 *  живых частей RANGED 22,2 против наших 5,9 при равном начале в 30. Возражение «мили — это заслон» снято его же
 *  числами: тиков без единого живого мили у него 37 % уже в первые 20 тиков боя, и он всё равно выигрывает.
 *
 *  4. Что делает правка. Подопечный выбирается по `InfluenceMap.restoredPower` — величине, которую v496 уже считает
 *  и которой шаг лекаря не спрашивал ни разу; рана осталась тай-брейком. Прибор `ward=` считает долю лекаре-тиков,
 *  где новое правило назвало ДРУГОГО подопечного. */
internal const val USE_WARD_BY_FIREPOWER = true

/** Доля, с которой считается часть, чьё оружие сейчас НЕ достаёт (v527). Замер: мили смежен с врагом 20-22 %
 *  тиков решающего окна против 51-83 % у стрелка, держащего цель в тройке. */
internal const val WEAPON_IDLE_SHARE = 0.25

/** ВЕЕР ИЛИ ВЫСТРЕЛ — ПО РАЗРУШЕННОМУ, А НЕ ПО ЧИСЛУ ЦЕЛЕЙ (v528).
 *
 *  1. Что стояло. `massValue > 2.5` при живых лекарях врага и `> 1.0` без них, с доводом в коде дословно: «веер
 *  размазывает урон по трём-пяти целям, и три лекаря (216 в тик) вылечивают его целиком».
 *
 *  2. Почему довод неверен. Лечение врага — ОБЩИЙ котёл на армию: три лекаря дают 216 в тик независимо от того,
 *  лежит наш урон на одном крипе или на пяти, и вычитают те же 216 в обоих случаях. Размазывание не увеличивает
 *  того, что стирается.
 *
 *  3. И вторая половина, которой не было ни в одном правиле. Урон ест тело СПЕРЕДИ, а оружие в телах этой арены
 *  стоит первым: к тому тику, когда крип умирает, все его оружейные части УЖЕ уничтожены. Значит убийство не
 *  снимает с врага ни одного очка выхода — его сняли раньше. Полезен только тот урон, что попадает в ОРУЖЕЙНЫЙ
 *  ЗАПАС цели (`weaponRoom` = хиты минус 100 x хвост); всё сверх него уходит в MOVE. Сосредоточение выше запаса —
 *  прямые потери, а не добродетель. Замер 26 реплеев против MetalicaX#17: нашего урона в уже разоружённые тела
 *  22-24 % и в победах, и в поражениях, у него 7-8 %; веером он стреляет 13-17 % выстрелов, мы 4-8 %.
 *
 *  4. Что делает правка. Выбор считается ценой: веер стоит сумму по целям min(доля x мощь, запас), выстрел —
 *  min(мощь, запас лучшей цели); берётся большее. Ни одного нового числа, старый порог 2.5 исчезает.
 *  Прибор `fanroom=` считает тики, где новое правило разошлось со старым. */
internal const val USE_FAN_BY_ROOM = true

/** РАЗДЕТЫЙ КРИП — ЭТО ЩИТ, А НЕ ЭВАКУИРОВАННЫЙ (v529).
 *
 *  1. Что стояло. Правило v135 (`USE_KITE_HELPLESS_OUT`) уводит из контакта того, кто ответить не может, с доводом
 *  «они дают 0 урона и держат его мили занятым бесплатной целью», а ступень `wounded` ведёт раздетого к лекарю.
 *
 *  2. Арифметика. У раздетого не осталось ничего, кроме 100 x хвост хитов тела и клетки, которую он занимает. Урон,
 *  принятый этим телом, — это урон, НЕ попавший в вооружённого: его мили вплотную кладёт 240 в тик, и три тика на
 *  раздетом стоят ему 720 хитов, то есть семи оружейных частей наших. Возврат раздетого в строй лечением стоит
 *  дороже: у `r6m6` порог 600, и первые 200 хитов чинят MOVE, не давая ничего. И цель он на себя берёт сам —
 *  модель его выбора (`wallTargetOf`, сверка 85-91 %) гласит «лекарь в досягаемости, иначе ближайший, иначе
 *  наименьшие хиты», а раздетый вплотную и есть ближайший с наименьшими хитами.
 *
 *  3. Замер (26 реплеев против MetalicaX#17). ЕГО разоружённые тела впитывают 22-24 % нашего урона — и в победах, и
 *  в поражениях, — причём другой цели в дальности у нас не было в 19 случаях из 22. НАШИ впитывают 7-8 % его огня.
 *  Живых раздетых в тиках 21-60 поражения у нас 4,7, у него 0,6: он их тратит, мы бережём без пользы.
 *
 *  4. Границы. Щит назначается только в контакте, только пока у нас ещё ДВА вооружённых крипа (иначе доктрина
 *  выживания: аннигиляция — проигрыш при любом счёте), и не трогает хранителей флагов: тело на флаге приносит очки.
 *  Прибор `shield=`. */
internal const val USE_STRIPPED_SCREEN = true

