/** ДЕБАФФ СОБСТВЕННОГО ВЫХОДА НЕ БЕРЁТСЯ, ПОКА ЕГО АРМИЯ ЦЕЛА (v530).
 *
 *  1. Правило арены. Захваченный флаг даёт очки ВЛАДЕЛЬЦУ и вешает на его же армию глобальный дебафф:
 *  уязвимость ×1 (5 очков в тик, входящий урон ×1,1), лечение ×2 (4 очка, ×0,75 и ×0,5), ATTACK ×2 (3 очка,
 *  ×0,8 и ×0,6), RANGED ×2 (3 очка, ×0,8 и ×0,6).
 *
 *  2. Цена дебаффа за одно очко счёта, по измеренному составу боя (наш урон 395 в тик, лечение 152, урон входящий
 *  319): уязвимость 32/5 = 6,4; лечение 38/4 = 9,5; RANGED 39/3 = 13,0; ATTACK 40/3 = 13,3. Уязвимость вдвое
