 *  бегуном на первых сорока тиках. Здесь условие — не контакт, а целость ЕГО армии: пока у него шесть и больше
 *  вооружённых, флаги, режущие наш выход, не берутся; как только армия сломана, открыто всё. Прибор `dbfveto=`. */
internal const val USE_NO_OUTPUT_DEBUFF_WHOLE_ARMY = true

/** ЦЕЛЬ ОГНЯ — ПО ОРУЖЕЙНОМУ ЗАПАСУ, А НЕ ПО БЛИЗОСТИ К СМЕРТИ (v531, продолжение v528 на ВЫБОР ЦЕЛИ).
