internal const val USE_FOCUS_BY_ROOM = true


internal const val PGS_ROUNDS = 1

/** БОЙ ПО РАЗМЕНУ ХИТОВ, А НЕ ПО КОНТАКТУ — И ДЛЯ ПОСТУРЫ, И ДЛЯ ЛИНИИ (v221, «тёплый контакт» спустя 131 версию).
 *  1. Замер. Разбор двух рейтинговых серий (v219, v220) по реплеям обеих сторон: в проигранных забегах армия
 *     38 % тиков стоит в постуре ANNIHILATE, и в 92 % этих тиков размена нет — обе стороны теряют меньше
 *     STALL_DAMAGE за окно LEDGER_WINDOW; это 35 % всего матча против 4 % в выигранных забегах (v219: 24 % против
 *     5 %). Флагов 2,97 против его 3,54, очков в тик 10,6 против 12,6 — те самые 0,6–2 в тик, которыми и проигрываем.
 *  2. Почему v90 (USE_COLD_CONTACT_POSTURE выше) не был тем же. Тот тумблер спрашивал «выстрел или удар по нам за
 *     STALL_TICKS» — а тычущая линия стреляет почти непрерывно, — и трогал ОДНО место из двух. Тёплый контакт держат
 *     два: боевая постура (`hotContact`), а когда она гаснет — «держим линию» (`holdLine`: его вооружённый в
 *     NEAR_RANGE, не толчок и не простой), которая тоже обнуляет флаг-цель. Прибор `warmhold` этапа 0 это
 *     подтвердил: на стенде 622 из 622 тиков, где постуру держал только тёплый контакт, ушли бы в линию. То есть v90
 *     мерил «ANNIHILATE → HOLD у поста», а не «армия идёт за флагами».
 *  3. Признак здесь — ХИТЫ обеих сторон за окно (`exchangeLive`, та же мера, что у клапана проигранной гонки v219):
 *     его мили вплотную — бой без вопросов (`meleeAdjacent`), загнанная неподвижная группа в досягаемости — бой
 *     (`cornered`, существующий стартер против стоящего лагеря). Постура и линия меняются одним тумблером: без
 *     второй половины первая бессмысленна. Доктрина паритета не трогается — флаг-цель армии по-прежнему проходит
 *     `captureAllowed` на каждый флаг, меняется только то, что тёплый контакт перестаёт её обнулять. */
/** ...И «НЕ БОЙ» — ТОЛЬКО С ИДУЩИМ ВРАГОМ (v221, найдено гейтом). Две строки лагеря стенда различают тычущий тур
 *  и запаркованный блоб там, где признак размена не различает (оба дают паузы по 20–50 тиков без обмена):
 *  1. `match31:camp` без починки кайта — FAIL 20121:22287 (см. USE_KITE_NEEDS_FIGHT);
 *  2. `match29:camp` с починкой кайта — FAIL 23804:24091 при базе 24030:6228: армия 1000+ тиков стоит постом в
 *     четырёх клетках от стоящего блоба (тёплый контакт 55 % тиков контакта), не атакует и флагов не берёт — тот
 *     же провал, что у v90 («без боя по контакту армия у фармящего блоба в 3–5 клетках не добивала»).
 *  Различие структурное — ДВИЖЕНИЕ: лагерь стоит, линия тура тычет и уходит. Признак берётся готовый, тот же, что
 *  у hisCentreMoved: центр его вооружённых за APPROACH_WINDOW сдвинулся меньше чем на APPROACH_WINDOW / 4 — стоит.
 *  Стоящий враг в контакте — бой: атакуем мы, как и было. Живой замер двух серий: в тёплых тиках проигранных
 *  забегов он стоит в 43 %, идёт в 57 % — правка сохраняет большую половину своей области. */
internal const val SPLIT_MIN = 3   // вторая группа не меньше трёх вооружённых: отставшие от колонны ходят по одному-два

internal const val RECALL_TICKS = 5

internal const val MEASURE_WINDOW = 10

internal const val PAIR_KEEP = 2

internal const val PRESS_RANGE = 3

internal const val PRESS_PACK = 2

/** Прижим — только на СТОЯЩУЮ линию: в контакте, под огнём врага, и ни один его мили не в MELEE_HOLD_RANGE + 1 от наших
 *  вооружённых PRESS_PATIENCE тиков подряд; включившись, держится, пока есть контакт. Прижим с первого тика контакта
 *  ОТВЕРГНУТ стендом: на идущего в атаку врага (rush/sleeper: его мили идут вплотную к ближайшему нашему) трое мили
 *  выходили из строя навстречу и были обезоружены за пять тиков втроём (m18 rush, t=66–71: M8A8 → M7/M8/M8, четвёртый
 *  мили без пачки простоял бой целым), армия потеряна к 110-му против чистой победы к 100-му; m13 sleeper — армия
 *  потеряна. Идущему навстречу строй нужен — он входит в наш фокус сам; прижим нужен тому, кто встал в трёх и стреляет.
 *  Три тика — цена вопроса: 300 в тик их огня, один обезоруженный. */
internal const val PRESS_PATIENCE = 3

/** Прижим не идёт навстречу атаке и не гонится за уходящим. «Их мили идут» — дистанция их мили до наших вооружённых
 *  сократилась на PRESS_CLOSING и больше за окно терпения (атакующий проходит 3 клетки за 3 тика, ползущий экран —
 *  одну): триггер «мили вплотную» без этого выпускал прижим навстречу броску (стенд m34 rush: прижим на 62-м, обмен
 *  16000→9440 против 14307 без него). «Цель уходит» — за два тика погони дистанция от наших мили до неё не сократилась
 *  (равная скорость): цель исключена из прижима на PRESS_GIVEUP тиков — экран стенда (m35 screen), отступающий от наших
 *  на двух клетках, превращал прижим в погоню под огнём стрелков и стоил армии. */
internal const val PRESS_CLOSING = 2

internal const val PRESS_GIVEUP = 20

/** ЗАЧИСТКА ФЛАГОВ ВМЕСТО ПОГОНИ (v124, серия 327–346 — быстрый гастролёр けろびー#4, три поражения по очкам при выигранном
 *  бое; стенд `blitz` 4-4 на v122): см. sweepObjective и chaseVeto. Правило v42 «позади против недерущегося — гнаться, стоять
 *  значит проиграть» верно, когда взять нечего; когда флаг под его одиночным хранителем проходит гейт стаи, взять его — это
 *  и есть не стоять.
 *  СТЕНД `blitz` НЕЙТРАЛЕН: по ярлыку «не дерётся» (v124) — ни одной цифры не сдвинул (ярлык гаснет, пока его хранители
 *  мелькают в досягаемости); по сухости погони (v124b: ни выстрела, ни удара PASSIVE_TICKS) — m28 3961:23980 → 23973:23418,
 *  m32 23975:21586 → 4980:23981, шесть карт без изменений, 4-4 → 4-4. Взятый флаг его пятёрка отбирает через 10–20 тиков
 *  (хранитель назначен на 388-м, снят на 397-м, его крип на флаге на 406-м), пока армия у следующего; зачистка не быстрее
 *  его отбора. Выключено как замер. */
/** Хранитель флага (v18): боец, стоящий на НАШЕМ флаге, при чужом бегуне в KEEP_RANGE и без нашего бегуна на флаге
 *  или назначенного к нему остаётся на месте, пока бегун врага рядом; в строю, в ударной группе и в цели армии он не
 *  участвует; снимается, когда флаг не наш, бегун врага ушёл, наш бегун встал на флаг или враг с боем в
 *  досягаемости. Пустой M1 не догнать: он отбегает от бойца и возвращается, едва тот уйдёт — армия брала R3, шла к
 *  D5 в сорока тиках, через четыре тика теряла R3, и цель прыгала между ними 1800 тиков, армия стояла, а враг с
 *  пятью флагами набирал вдвое (стенд m8 kite). */
internal const val KEEP_RANGE = 10

/** Ловимость (см. catchable/evasive): окно наблюдения за движением врага, и поводок — дальше стольких клеток от
 *  центра вооружённой армии боец при враге рядом идёт к центру, а не к цели. Уходящего с равной скоростью не
 *  догнать никогда: в матче 5 армия 80 тиков гналась за тремя мили-приманками через всю карту, потом два мили —
 *  40 клеток за одиноким лекарем, и половина армии осталась одна против пяти стрелков с лекарями. */
internal const val CHASE_WINDOW = 8

/** ТРАССА РЕШЕНИЙ (v108; с v458 — общая, см. `Why` в Tables.kt и `traceNow` в Clock.kt): рубильник строки `trace t=` — на бойца
 *  выигравшие строки лестницы и шага и первый ложный конъюнкт факта каждой строки выше; печатается только в окне тиков (на стенде
 *  `TRACE=t0-t1`). До v458 здесь жил ручной прибор ОДНОГО факта — строка `why t=N:` на тик со всеми праздными мили и сводка
 *  `why-sum`: копия конъюнктов `engage` рядом с фактом, которая однажды уже разошлась с ним (v203). Снят; взамен — счётчики
 *  `whynot t=` у каждого сложного факта. */
internal const val TRACE_WHY = true

internal const val TOUCH_WINDOW = 50       // окно замера «достаём ли»: тиков контакта

/** ДОЛЯ КАСАНИЙ БЕРЁТСЯ ИЗ НЕПОЛНОГО ОКНА, А НЕ ЗАМЕНЯЕТСЯ ЕДИНИЦЕЙ (v502, см. `touchShare`). Полное окно —
 *  TOUCH_WINDOW = 50 тиков контакта ПОДРЯД, потому что история чистится на каждом тике без контакта. Бой против
 *  MetalicaX#17 решается за 40-50 тиков при мерцающем контакте, и окно часто не наполняется вовсе; тогда доля равна
 *  1.0 — «мили бьёт вплотную каждый тик». Настоящее прилегание измерено прибором `madj=` (v501, 14 рук): около
 *  20 %. То есть мера мощи завышает мили впятеро, а на ней стоят цена захвата, пол паритета, постура и отход;
 *  правило v433, которое эту долю и ввело, в таких матчах не действует вовсе.
 *  Замер `touchl=` по тем же 14 рукам против MetalicaX#17 (4-10): в четырёх победах 8, 16, 18, 23 — ни разу 100;
 *  в десяти поражениях 10, 14, 1, 16, 11 и ПЯТЬ РАЗ 100, то есть «замера нет» встречается в половине поражений и
 *  ни в одной победе. Точный критерий на этих числах p ≈ 0,25 — сам по себе не довод; довод в том, что значение по
 *  умолчанию заведомо неверно впятеро, а среднее по пяти замерам неверно уже не заведомо.
 *  ⚠️ ОТВЕРГНУТО ЖИВЬЁМ (v502). A/B 16+16 против MetalicaX#17: 3-13 против 5-11 у базы v501. Выигрыша нет, и это
 *  третий случай за день, когда верное по существу исправление меры не двигает исход: мера мощи, видимо, не стоит
 *  на пути решения, которое проигрывает эти бои. Тумблер выключен, число записано; сама правка останется здесь
 *  готовой на случай, если предмет всплывёт с другой стороны. */
internal const val USE_TOUCH_PARTIAL_WINDOW = false

/** Сколько замеров касания нужно, чтобы средним по ним пользоваться вместо единицы (v502). Пять — тик контакта
 *  даёт замер, а пять тиков боя уже отличают «мили в куче» от «мили не достаёт». */
internal const val TOUCH_MIN_SAMPLES = 5

internal const val LEASH_RANGE = 8

// окно «марш не идёт» (см. простой): дольше самого длинного ЗАКОННОГО стояния на марше — ожидания отставших, —
// чтобы сплочение не считалось простоем; названного числа здесь нет, оно считается из этих двух
internal const val MARCH_STALL_TICKS = COHESION_PATIENCE + STALL_TICKS

/** Бегство скаута: от боевого врага ближе SCOUT_FLEE_TRIGGER — прочь, путь бегства ищется до клетки дальше
 *  SCOUT_FLEE_RANGE от ВСЕХ врагов. С дальностью цели 3 ближайшая «безопасная» клетка лежала на два шага глубже в
 *  углу H4, и скаут бежал в тупик, пока армия врага шла в устье (матч 12, t=117); цель дальше глубины кармана
 *  ведёт через устье наружу. Триггер больше досягаемости на глубину кармана: на равной скорости уходить надо,
 *  пока устье открыто, а не когда враг в четырёх клетках. Скаут — страховка от аннигиляции (пустой MOVE не
 *  устаёт и не догоняется на открытом месте), его гибель стоит матча. */
internal const val SCOUT_FLEE_TRIGGER = 8

/** ДЕРЖАТЕЛЬ НЕ УХОДИТ С ВЗЯТОГО ФЛАГА (v297), пока его крип — любой, скауты тоже — не дальше этого от флага: такой встаёт
 *  на свободную клетку, едва мы уходим, а занятую не берёт вовсе. Разбор 44 матчей v296 по реплеям (Opus, замер сходов с
 *  наших флагов без замены): при его крипе в 9–12 клетках от флага сход скаута — флаг потерян до нашего возвращения в 74 %
 *  (けろびー, медиана 12 тиков), 53 % (Coldkimchi#2), 77 % (MetalicaX); в 6–8 — 95 / 67 / 78 %; дальше 16 — 0–27 %, за
 *  30 тиков 0–14 %. Против けろびー#19 (0-16) скаут уходил к следующему флагу сам 20 раз за матч, отряд командира после
 *  захвата возвращался в армию (130 из 194 сходов вооружённых) — взять новый ценой прежнего, размен без выигрыша: 7,4 тыс.
 *  против 24,3 тыс. при целых армиях. Дальше этого круга держатель свободен, и обход флагов против кулака остаётся */
internal const val HOLD_WATCH = 12

/** ОН НЕ БЬЁТ НАШИХ, СТОЯЩИХ ГРУППОЙ (v298): окно и порог урона по нашим крипам, у которых свой крип с оружием в двух
 *  клетках. Разбор 41 матча v296 по реплеям: けろびー за весь матч наносит «группе» 0–300 хитов в 17 играх из 21 (максимум
 *  4,5 тыс. на 43 тиках), одиночкам — 0,3–6,7 тыс.; Coldkimchi#2 — 14–94 тыс. с 41–47-го тика, MetalicaX — 5–19 тыс. с
 *  48–76-го. Пока за GROUP_WINDOW тиков урон по группе не больше GROUP_SAFE_DMG (и режим включился, когда его армия не
 *  была одним кулаком), отряд из двух ему не цель: командир выпускает пары, не меряя выпуск всей его армией */
internal const val GROUP_WINDOW = 40
internal const val GROUP_SAFE_DMG = 300

/** Против сомкнутого в кулак врага командир не берёт режим боя (v351, см. fightNow): 8 побед и 32 поражения против
 *  MetalicaX#15 различаются режимом в первые 60 тиков контакта — 1 окно FIGHT против 4, и 26 поражений из 32 берут
 *  режим боя раньше первой нашей смерти. */
internal const val USE_NO_FIST_FIGHT = true

/** Запасной ход стрелка выбирается среди клеток, СОХРАНЯЮЩИХ цель в дальности (v421, см. проход ranged): у лекаря
 *  это правило стоит с v183, у стрелка его не было — запасная клетка ранжировалась только опасностью и уводила из
 *  дальности. Чистая пара 16 игр против MetalicaX#13: тиков со сходимостью >= 3 стволов на одной цели 1,00 в
 *  победах против 0,73 +- 0,14 в поражениях; порог посчитан из арифметики (выстрел 60, его лечение 129-147 на цель).
 *  Прибор fall= — сколько запасных ходов сохранили дальность и сколько нет. */
internal const val USE_RANGED_FALLBACK_KEEPS_REACH = true

/** Удар мили входит в цену клетки явно, в единицах урона (v425, см. scoreMelee): наш мили вплотную даёт 240 в тик,
 *  тогда как три стрелка дают 180 против его лечения 129-147, то есть чистыми 33-51 — лечение пробивает мили, а не
 *  стрелки. Чистая пара 16 игр против MetalicaX#13: наш мили до его ближайшего 1,35 +- 0,11 в победах против
 *  1,95 +- 0,57 в поражениях, разрез по 1,45 даёт 6 побед из 6 против 0 из 9. */
internal const val USE_MELEE_STRIKE_VALUE = true

/** ...И СТОИТ ОН СТОЛЬКО, СКОЛЬКО ДОБАВЛЯЕТ К ЧИСТОМУ УРОНУ (v504, см. Deal.strikeValue). Валовая мера v425 оценивает
 *  клетку у свежего врага ровно так же, как клетку у того, кого УЖЕ рубят двое: оба слагаемых равны 240, и выбор
 *  между ними отдан опасности и фронту, то есть мили расходятся. Арифметика говорит обратное: цель под его лекарями
 *  лечится на 140-288 в тик, поэтому один удар 240 даёт чистыми 0-100, два 192-480, три 432-720 — ТРЕТИЙ мили
 *  удваивает чистый урон, и премия за сходимость существует только у мили.
 *
 *  ⚠️ У СТРЕЛКА ТА ЖЕ ФОРМА ОТВЕРГНУТА ДВАЖДЫ (v483 и v484, см. USE_RANGED_SHOT_NET) — и это ДОВОД ЗА правку, а не
 *  против. Замер 32 игр против MetalicaX#17 (20.09.2026), тик 70, когда в 22 поражениях из 24 ещё никто не погиб:
 *  сходимость СТРЕЛКОВ `concmax` равна 4-5 в ОБЕИХ группах — чинить там было нечего, поэтому обе формы и не
 *  сдвинули исход; сходимость МИЛИ `mconcmax` >= 3 в 8 победах из 8 (100 %) против 7 поражений из 24 (29 %) при
 *  одинаковом примыкании `madj` 12-26. Арифметика ту же разницу называет: три стрелка дают 180 против лечения 288 и
 *  не пробивают НИКОГДА, сколько их ни своди, — три мили дают 720 и пробивают. Форма взята действующая (мягкое
 *  насыщение `мой * (чужие + мой) / (чужие + мой + лечение)`), а не отвергнутая разность обрезанных: она монотонна
 *  по числу ударов и не обнуляет слагаемое на непробиваемой цели, то есть не гонит мили от врага.
 *
 *  ⚠️ ОТВЕРГНУТА СВОИМ ЖЕ ПРИБОРОМ И ВМЕСТЕ С ПОСЫЛКОЙ (v505, A/B 16+16 против MetalicaX#17, 21.09.2026). Счёт
 *  6-10 у правки против 3-13 у базы — вдвое больше побед, но при p ~ 0,44 это не различение; а прибор, ради
 *  которого правка сделана, ушёл В ОБРАТНУЮ СТОРОНУ: `mconcmax` >= 3 на t=70 у базы 10/16, у правки 8/16,
 *  медиана 3 против 2. Мили не сошлись, значит счёт к правке отношения не имеет.
 *
 *  ⚠️ И ВАЖНЕЕ ТОГО: НЕ ВОСПРОИЗВЕЛАСЬ САМА ПОСЫЛКА. На тех же 32 свежих играх `mconcmax` >= 3 в победах 4/9
 *  (44 %) против 14/23 (61 %) в поражениях, медианы 2 против 3 — то есть разделитель поменял знак. Замер, из
 *  которого правка выросла (32 игры 20.09.2026: 8/8 против 7/24), был особенностью выборки, а не свойством игры.
 *  Это тот же класс ошибки, что записан в `divider-is-not-a-lever`: величина, делящая исходы, оказалась
 *  следствием, и проверять её надо НА ДРУГОЙ выборке ДО правки, а не после. Тумблер выключен, ветка «цена удара
 *  мили» закрыта обеими формами (валовая v425 действует, предельная отвергнута), как и у стрелка. */
internal const val USE_MELEE_STRIKE_NET = false

/** Выстрел входит в цену клетки стрелка явно, в единицах урона (v427, см. scoreRanged) — тот же пропуск, что у мили
 *  в v425: клетка вне дальности не стреляет вовсе, а ранг различал её только безразмерным полем притяжения. Выстрел
 *  60 против удара мили 240, то есть слагаемое вчетверо меньше и расстановку не переворачивает. */
internal const val USE_RANGED_SHOT_VALUE = true

/** ...И СТОИТ ОН СТОЛЬКО, СКОЛЬКО ДОБАВЛЯЕТ К ЧИСТОМУ УРОНУ (v482, см. Deal.shotValue). Валовая мера v427 оценивает
 *  клетку с одиночным выстрелом ровно так же, как клетку, где огонь армии сходится, — а арифметика класса, записанная
 *  в файле пятикратно, говорит, что одиночные 60 против лечения 129-147 приносят ЧИСТЫМИ НОЛЬ и цель пробивают три
 *  ствола. Предельный вклад (чистый урон по цели со мной минус без меня) эту разницу называет и собирает стволы ценой
 *  клетки, не таща стрелка к общей цели: притяжение к фокусу отвергнуто живьём (v268/v269, 9-7 и 8-8 при 7-9, стволов
 *  на фокусе 0,62 против 0,75). Прибор предмета — `shotnet=`, он считает при ОБОИХ положениях тумблера.
 *  ⚠️ Первая форма (v483, разность обрезанных) отвергнута своим прибором — 1-6 против 1-6 живьём при выстрелах
 *  впустую 14,3 % против 12,8 %; разбор формы — в KDoc `Deal.shotValue`.
 *  ⚠️ И ВТОРАЯ ФОРМА (v484, мягкое насыщение) ОТВЕРГНУТА ЖИВЬЁМ: A/B 8+8 против MetalicaX#17 дал 0-8 против
 *  2-6 у базы, при том что гейт обещал +1 уничтожение армии врага и отрыв +3465. Тумблер выключен; ветка
 *  «цена выстрела» закрыта обеими формами, предмет поражения лежит не здесь (см. docs, режим RACE в бою). */
internal const val USE_RANGED_SHOT_NET = false

/** В счёт мощи идут БОЕВЫЕ хиты — те, что защищают ещё живые боевые части (v428, см. fightingHits). Движок снимает
 *  части по порядку, спереди назад: у мили ATTACK стоит впереди и он разоружается на 800 из 1600 хитов, у лекаря
 *  HEAL сзади и его 1200 боевые целиком. Мера брала полные хиты и завышала мили вдвое. */
internal const val USE_FIGHTING_HITS = true

/** Ворота первого боя держатся, пока бой не РЕШЁН, а не пока он не начался (v420, см. captureBlock). Разрез 64 игр
 *  против Coldkimchi#1 по прибору rate= на t=150: темп 0 — 16-11 (59 %), темп больше нуля — 3-34 (8 %). Тумблер
 *  заведён, чтобы снять базу: гейт стенда к этой ветке слеп (отчёт побайтово тождествен базе). */
internal const val USE_FIRST_FIGHT_UNSETTLED = false

/** ДОЛЯ КАСАНИЙ МИЛИ В МЕРЕ МОЩИ — ПОСЛЕДНЯЯ ИЗМЕРЕННАЯ, А НЕ ЕДИНИЦА ВНЕ КОНТАКТА (v433, см. powerOf). ATTACK бьёт
