/** ЗАЩЁЛКА «ОН ДРАЛСЯ СОМКНУТЫМ» СНИМАЕТСЯ ЗАМЕРОМ «ОН НЕ УСПЕВАЕТ НАС УНИЧТОЖИТЬ» (v534, см. cannotWipeUs).
 *
 *  `fightMassedSeen` — защёлка на ОДНО событие, которую v434 и v438 поставили сторожем сразу в двух местах: она
 *  заставляет ворота захвата считать цену флага по ВСЕЙ его армии (`foughtFoe`) и выключает режим пар
 *  (`USE_PAIRS_NOT_VS_FIGHTER`). Против けろびー#19 замер по 59 матчам говорит, что сторож стоит там, где боя нет:
 *  защёлка держится 92 % тиков в поражениях и 80 % в победах, при том что в тех же матчах мы достаём его 1–5 %
 *  тиков, он нас 1–6 %, наших тел в конце 12,6 из 14 и его 11,8, kills = 0. Цена видна числом: доля разрешённых
 *  захватов падает по третям матча 0,21 → 0,11 → 0,05 (в победах 0,19 → 0,18 → 0,33), бюджет выпуска 4,56 → 3,73 →
 *  2,87 (в победах ровно 5,36 / 5,49 / 5,40), и вслед за ними бегуны 5,68 → 4,05 → 2,33 (в победах 6,93 / 6,94 /
 *  6,65). Бегуны при этом не гибнут — их некуда посылать: флаг запрещён, и они возвращаются в ядро. Очки в тик по
 *  третям: наши 11,11 → 10,24 → 7,41 против его 11,45 → 14,76 → 17,59 при 25 очках в тик на все семь флагов.
 *
 *  Замена — не другая защёлка, а ВЕЛИЧИНА: успевает ли он снять с нас все хиты за оставшиеся тики, если остаток
 *  матча будет драться так же сильно, как в самый сильный свой отрезок. Пик берётся по окну GROUP_WINDOW от
 *  полного урона по армии; лечение считается по телам с дебаффами (в том числе дебаффом БЕРУЩЕГОСЯ флага), урон —
 *  с его множителем получаемого урона. Если лечение перекрывает пик, уничтожить нас он не может вовсе; иначе
 *  сравнивается `хиты / (пик − лечение)` с остатком тиков. Новых чисел нет: окно, множители и лимит тиков — уже
 *  существующие. Ворота открываются только ПОСЛЕ первого размена и не раньше, чем через GROUP_WINDOW после него, —
 *  до первого боя пик равен нулю и мерить нечего, а дебют защищён v530 (`USE_NO_OUTPUT_DEBUFF_WHOLE_ARMY`).
 *
 *  Возражение v433–v434 (у Coldkimchi#1 «не бьёт» — это пауза между боями) правило не воскрешает: пик за матч
 *  паузой не гасится, он помнит самый сильный отрезок до конца матча. Лечение берётся общим котлом — армию
 *  уничтожают целиком, и лечение, которое ляжет, ляжет; запас против けろびー при этом не на волосок: его пиковый
 *  темп против нашего лечения расходятся в разы, а не на проценты. */
internal const val USE_UNWIPEABLE_OPENS = true

/** ЛЕКАРЬ ДЕРЖИТ ФЛАГ, КОГДА БОЯ НЕТ (v535, см. commandRace, updateKeepers, grabberOf).
 *
 *  Два правила держали трёх лекарей из четырнадцати в ядре при любых обстоятельствах: состав гонки отбирался по
