 *  (59 матчей, 27 651 флаго-срез): тело держит флаг в ШЕСТЬ раз надёжнее. Тел на флагах у нас 3,5 из 14 в победах и
 *  1,74 в последней трети поражений, при том что 53,7 % тиков поражения девять и более наших крипов стоят вне
 *  досягаемости кого бы то ни было. Лекарь — лучшее из свободных тел: h6m6 это 1200 хитов и 72 лечения СЕБЕ в тик,
 *  то есть гарнизон, который гастролёру-одиночке не сбить.
 *
 *  Страховка не новая: хранитель в режиме пар уходит по правилу v366 — «его возможный урон по моей клетке больше
 *  фактического лечения на ней», — и для лекаря на флаге фактическое лечение считается с его собственными частями.
 *  Вне режима пар оба прежних запрета остаются как были. */
internal const val USE_HEALER_HOLDS_FLAG = true

/** ЧИСТАЯ ПОТЕРЯ — УЖЕ ЗА ВЫЧЕТОМ ЛЕЧЕНИЯ, И ВЫЧИТАТЬ ЕГО ВТОРОЙ РАЗ НЕЛЬЗЯ (v536, см. cannotWipeUs, wipeByHits).
 *
 *  Дефект v534, найденный разбором поражений от `Coldkimchi#1`. Пик его урона берётся из `ourDamageTaken` — суммы
 *  хитов, которых армия НЕДОСЧИТАЛАСЬ за тик, то есть величины, в которой лечение уже учтено. v534 вычитала из неё
 *  общий котёл лечения (216 в тик при трёх лекарях) ещё раз, и ворота отвечали «он не может нас уничтожить» почти
 *  всегда: в трёх разгромных матчах прибор показал `unwipe` от 942/942 до 1411/2540 при том, что он снимал 13 тел из
 *  14 за 160–250 тиков, теряя 0–1 своё. Обмен телами 13:0, 13:1, 13:0. Утверждение ворот было ложным по факту матча.
 *
 *  Вторая половина правки — вторая оценка ТОЙ ЖЕ величины, по телам: при темпе, с каким он снимает наши тела с начала
 *  матча, хватит ли ему оставшихся тиков на те, что ещё стоят. Тела — итог, которого модель хитов не видит по
 *  построению: общий котёл лечения не спасает того, кого сосредоточили, и с каждой смертью сам котёл уменьшается.
 *  Берётся МЕНЬШАЯ из двух оценок: это две меры одной величины, и осторожная — та, что раньше говорит «успеет».
 *
 *  Замер поправки по телам на сохранённых логах: в трёх разгромах она закрывает ворота к t=500 (83, 136 и 136 тиков
 *  до уничтожения против 1500 оставшихся), в девяти победах над けろびー не закрывает никогда (потерь нет вовсе).
 *  Новых чисел нет: обе оценки — отношения замеренного к остатку матча.
 *
 *  ⚠️ Тумблер управляет ТОЛЬКО второй оценкой (по телам). Снятие двойного учёта лечения тумблера не имеет намеренно:
 *  это не выбор поведения, а исправление ложного утверждения — как в v533. */
