 *  против 1,2,3,4,4,6,6 у контроля), и обе победы контроля пришлись на `hulk`=6 — тот же порог, что в истории.
 *  Что должно быть верно, чтобы правило заработало: мера должна считать путь бегуна ДО клетки, а не два тика на ней.
