/** ГОРСТКА ЗА ФЛАГОМ РАЗМЕРОМ ПО ЕГО СТРАЖАМ (v549, решение оператора 22.09.2026, см. RaceParties).
 *
 *  Правило арены, названное оператором: **крип не обязан стоять на флаге, чтобы шли очки.** Флаг захватывается
 *  мгновенно вставшим на него и остаётся нашим ПОСЛЕ схода — владение держится, пока его не перевернёт чужое тело.
 *  Отсюда доктрина: не стоять до последнего, теряя оружейные части, а отходить и возвращаться **группой, способной
 *  отбить флаг и прогнать врага**.
 *
 *  Что мешало: размер горстки за чужим флагом был жёстко равен двум (`need = if (safe || guarded) 2 …`), а у него по
 *  **два стража на флаг** (замер: 73,3 % его флаго-тиков под охраной, в среднем 2,0 стража). Двойка против двух
 *  `M8A8` по 240 урона в тик не выигрывает, и стоящий ниже отказ «его стражи сильнее нашей горстки» пропускал такой
 *  флаг СОВСЕМ. Оттого мы и не отбивали: флагов с нашим телом 2,25 -> 1,82 в поражениях против 2,44 -> 3,00 в
 *  победах, при одном флаге к t=400 побед 0 из 17.
 *
 *  Теперь размер считается из состояния: горстка растёт, пока её мощь не превзойдёт его стражей у ЭТОГО флага.
 *  Новых чисел нет — сравниваются те же `ourPowerOf` и `enemyPowerOf`, которыми меряется всякий размен, а ядро
 *  по-прежнему обязано остаться сильнее (`coreHolds`). Отказ остаётся отказом только если группа не набралась.
 *
 *  Заодно отключено `USE_ARMED_GARRISON_VS_GARRISON` (v548): сажать на флаг бойца вместо скаута — это ровно то
 *  «стоять телом и терять оружейные части», от которого правило и уходит. */
