 *
 *  В коде записано прямо: «вооружённый крип, приведённый к флагу как боец, флага НЕ БЕРЁТ — захват делают бегуны»
 *  (v160). Против кулака бегунов нет вовсе (v553 обнуляет выпуск), и армия ходит к флагам впустую: прибор
 *  `mguard=4801` при **нуле наших флагов** в конце и счёте 2 692 : 19 262. В том же отборе «кто шагнёт на флаг»
 *  стоял пропуск флага-ЦЕЛИ армии — то есть ровно того, к которому её ведут.
 *
 *  Флаг остаётся нашим после схода с клетки (правило арены, оператор 22.09.2026), поэтому шаг на клетку и есть весь
 *  захват: армии не нужно ни стоять, ни выделять бегуна. Послабление узкое — только пока распознан кулак. */
internal const val USE_ARMY_GRABS_VS_FIST = true

/** РАЗРЕШЁННЫЙ ЗАХВАТ В ОДНОМ ШАГЕ ВЫШЕ ПРИКАЗА КОМАНДИРА (v556, см. steps(), freeStep, submit).
 *
 *  Разбор реплея поражения от けろびー#22 (матч 6ab28988, 22.09.2026) назвал место точно. С 806-го тика до конца
 *  (494 тика) обе армии НЕ ДЕЛАЮТ НИ ШАГА: он поставил девять вооружённых на центральный D5 (49,49) и держит все
 *  семь флагов (`rate=0/25`), а наши СЕМЬ ЦЕЛЫХ тел (2×M8A8 и 4×M6R6 по полным хитам, ближайший враг в 34 клетках)
 *  колеблются с периодом 2 вокруг его R3 (85,49) — один стоит на (84,49), вплотную, — и на клетку флага не встаёт
 *  ни разу. Счёт 3 700 : 20 772.
 *
 *  Цель выбрана верно и ворота не мешают: `obj=(85,49)` все 500 тиков, `objdrop` растёт (кандидаты считаются),
 *  `mguard` +14/тик (флаг взят маршем v554), отказ `gate` ЗАМЕР. Замер и `stray` — счётчик отменённых воротами шагов
 *  НА клетку флага: он не растёт, то есть шаг на флаг не предлагает никто, и отменять нечего.
 *
 *  Причина — в лестнице шага. Послабление «клетка чужого флага открыта назначенному захватчику» снимает клетку из
 *  `blockedSet` ТОЛЬКО внутри `freeStep` (строка `free`, последняя), а строка `order` стоит выше и отдаёт клетку
 *  командира буквально (v172, «приказ — закон»). Гистограмма шага в том же окне: `order` +3/тик, `free` +4/тик из
 *  семи тел. Назначенный захватчик — ближайший ВООРУЖЁННЫЙ, то есть ровно тот, кого командир и ставит в строй:
 *  правило захвата записано, но до ветки исполнения не доходит.
 *
 *  Правка ставит захват туда же, куда v282 поставила ворота, — в цепочку шага, одной строкой на все ветки: крип,
 *  стоящий вплотную к НЕ нашему флагу, которому ворота (`captureBlock`, тот же вызов, что у бегуна) захват
 *  РАЗРЕШАЮТ, шагает на флаг, и эта строка стоит выше приказа. Ворота не обойдены — обойдён только приказ.
 *  Основание цены — правило арены (оператор 22.09.2026): флаг остаётся нашим после схода с клетки, поэтому цена шага
 *  равна одному тику вне клетки строя, а выигрыш — 3–5 очков в тик до тех пор, пока флаг не отобьют. Выживание
 *  (`flee`) и пост хранителя остаются выше: строка стоит ПОД ними. */
internal const val USE_CAPTURE_OUTRANKS_ORDER = true

/** НЕЗАЩИЩЁННЫЙ ФЛАГ ПРИ ПРОИГРАННОЙ ПРОЕКЦИИ БЕРЁТСЯ ПО ПОСЛАБЛЕННОМУ ПОЛУ (v559, см. lostRaceNow, captureGates).
 *
 *  v556 открыла шаг на флаг (строка `capture` выше приказа) и дала первую победу над けろびー#22 за 50 игр, счёт
 *  5 858 : 16 378 против 3 482 : 18 807. Прибор `cap3` назвал остаток: из 4 109 крипо-тиков «стою вплотную к
 *  свободному чужому флагу» ворота разрешили 119, то есть 2,9 %. Разбивка `cap3why=` по 12 играм: **паритет 2 332
 *  отказа (58,4 %)**, rush.unflagged 558, first.fight 416, rush.approach 385, enough 250, contact.mass 49.
 *
 *  Пол паритета сравнивает нашу мощь ПОСЛЕ захвата (с дебаффом флага) против его мощи, и против этого соперника
 *  сравнение безнадёжно: его вооружённых 9 весь матч, наших 9 → 6 (реплей 6ab28988, `track`). Послабление для
 *  ровно этого случая в боте есть — `PARITY_FLOOR_LOST = 0.75` при проигранной гонке, — но клапан `lostRaceNow`
 *  требует сверх проекции ещё и «за окно мы потеряли меньше STALL_DAMAGE» (v218). Против けろびー#22 это условие
 *  верно в 7 % проверок (`lostrace` 152/2217, 135/2064), и послабление не открывается почти никогда.
 *
 *  Клапан по размену защищает АРМИЮ В БОЮ: пол существует ради «не потерять нашу армию за флаги» (v218 дословно).
 *  У флага, до которого ни один его боевой крип не достаёт (дальше RANGED_RANGE + 1) и на котором никто не стоит,
 *  защищать в этот тик нечего — размена там не будет, а по правилу арены (оператор 22.09.2026) флаг остаётся нашим
 *  после схода с клетки. Поэтому условие сужено: проекция гонки проиграна И флаг вне его досягаемости → пол
 *  PARITY_FLOOR_LOST. Доктрина не тронута: в оспариваемом захвате пол прежний, новых чисел нет — взяты те же
 *  PARITY_FLOOR_LOST и RANGED_RANGE. Прибор `capfree=` считает, как часто послабление вообще применимо. */
internal const val USE_LOST_RACE_FLOOR_UNCONTESTED = false
// ⚠️ ОТВЕРГНУТО СВОИМ ЖЕ ПРИБОРОМ (v559, 5 живых игр против けろびー#22). Послабление ПРИМЕНИМО в 96 % вопросов
// (`capfree` 2 659/2 770), а разрешений не прибавилось: 43 из 2 928 против 119 из 4 109 у v558 — то есть пол 0,75
// разрыв не перекрывает, потому что к концу матча нас ВДВОЕ меньше (6 тел против 12). Тот же замер показал, что
// предмета в хвосте нет вовсе: до t≈810 ворота разрешают ВСЁ (13 из 13), а обвал идёт между t=410 и t=910, когда
// армия падает с 12 до 6. Чтобы правило заработало, должно стать верным: наша мощь после захвата держится выше
// 0,75 его мощи, то есть мы перестали терять тела поодиночке (см. реплей 6ab2a493).

/** КУЛАК ДЕРЖИТ АРМИЮ И БЕЗ КОНТАКТА, ПОКА ЕГО АРМИЯ — ОХОТЯЩИЙСЯ КУЛАК (v560, см. ArmyTick.fistNow,
 *  USE_FIST_EVERY_STEP).
 *
 *  Реплей 6ab2a493 (けろびー#22, 22.09.2026) назвал причину поражения одним числом: наших тел погибло ВОСЕМЬ, и
 *  СЕМЬ из них — в одиночку (рядом 0–1 своих, 3–7 его боевых), в разных концах карты: (3,92), (89,3), (7,3),
 *  (62,52), (73,33), (30,65), (11,72). Его четыре потери — все в одном окне t=367–446, единственном, где наша
 *  группа дралась с его группой вместе. Его вооружённых девять весь матч, наших девять → шесть. Отсюда и отказ
 *  ворот захвата по паритету в 58 % (см. USE_LOST_RACE_FLOOR_UNCONTESTED): к концу нас вдвое меньше.
 *
 *  Запрет отрываться от медианы боевых в боте есть с v490 и действует на каждый шаг — но включается он только
 *  `meas.fight.contact`. Прибор в том же матче: `fist=0/0`, то есть за весь матч он не сработал НИ РАЗУ, при
 *  `fist2=1170` из ~1300 тиков, где его кулак распознан. Правило, которое держит армию вместе, выключено ровно
 *  против того соперника, который карает отставших: он не даёт контакта, он объезжает флаги одной девяткой и
 *  съедает наших по одному.
 *
 *  Комментарий v490 объясняет узость: «вне боя кулака нет и запрет не действует — армия ходит за флагами». Против
 *  объездчика это и есть смерть: армия ходит за флагами ПООДИНОЧКЕ. Запрет при этом флагов не отменяет — он не
 *  выбирает клетку и не спорит с выбором, а снимает только шаг, уводящий дальше FIST_RADIUS + STRAGGLER_SLACK И
 *  дальше, чем крип стоит сейчас; возвращение к своим разрешено всегда, спасение (SURVIVE) не трогается. Вместе с
 *  `capture` (v556) это и есть доктрина оператора от 22.09.2026: армия объезжает флаги ОДНОЙ группой, а встаёт на
 *  флаг тот, кто оказался вплотную. Новых чисел нет: радиус, зазор и признак кулака уже измерены. */
internal const val USE_FIST_VS_HUNTING_FIST = true

/** ЦЕЛЬ, КОТОРУЮ ЗАПРЕЩАЮТ ВОРОТА, — ЭТО «БРАТЬ НЕЧЕГО» (v563, см. StrategyInputs.raceLostNothingToTake,
 *  USE_ENGAGE_WHEN_RACE_LOST).
 *
 *  **Разделитель на 52 играх против けろびー#22 (v556–v562) чистый: обе победы — это один выигранный групповой бой
 *  против его армии, а в 49 поражениях из 50 его армия НИ РАЗУ не опускалась ниже 10 тел.** Реплеи обеих побед
 *  (6ab2965e, 6ab2af3c): наши 6–7 тел разгромили его 10–11 в одной схватке — во второй он потерял шесть тел за
 *  15 тиков (t=1023–1038), — и после этого флаги вернулись к нам (`rate=25/0` в первой).
 *
 *  Основание — не корреляция, а арифметика арены. Флаг бьёт по своему владельцу, и соперник-объездчик к t≈900
 *  держит все семь: живые эффекты в логе победы — его урон ×0,6, лечение ×0,5, получаемый урон ×1,1, а наши
 *  множители единичные. Дальше он паркуется, и это единственное состояние матча, где его армия заведомо ослаблена.
 *
 *  Правило «начать размен, когда гонка проиграна и брать нечего» (v538/v540) ровно для этого есть — и в замёрзшем
 *  хвосте молчит: `engage` стоит на 253 с t=900 до t=1300. Причина — фантомная цель. Марш к охраняемому флагу
 *  (v542/v554) выбирает цель В ОБХОД ворот захвата (`mguard` +14 в тик), а шаг на клетку ворота потом не пускают
 *  (паритет — 58 % отказов, см. USE_LOST_RACE_FLOOR_UNCONTESTED). Цель есть, взять её нельзя, и «брать нечего»
 *  ложно — армия 494 тика стоит у его R3 при семи целых телах.
 *
 *  Понятие «есть, но не взять» в коде уже записано (v539) и реализовано только через гарнизон. Здесь добавлена его
 *  самая прямая форма: цель, которую запрещают ворота. Новых чисел нет — вопрос задаётся тем же `captureBlock`, не
 *  всерьёз, чтобы не трогать счётчики ворот. Прибор `engbar=` — тиков с запрещённой целью / из них с открытым
 *  разменом. */
internal const val USE_ENGAGE_VS_BARRED_OBJECTIVE = true

/** ХРАНИТЕЛЬ УХОДИТ ВМЕСТЕ С ГРУППОЙ, ПОКА ЕГО АРМИЯ — ОДИН КУЛАК (v565, см. updateKeepers).
 *
 *  Разбор схваток v556–v563: настоящие бои мы выигрываем в 17 случаях из 23, а 104 тела теряем в 41 эпизоде, где он
 *  не теряет никого. Путь каждой такой смерти по реплею 6ab2a493 (последние 60 тиков) один и тот же: крип СТОИТ НА
 *  ФЛАГЕ 40–60 тиков, пока группа уходит дальше — медиана своих отдаляется с 2 до 12–18 клеток, — затем приходит
 *  его кулак из 5–7, и уйти уже нельзя, потому что скорость у всех одна. Мили на D5 (группа 2 → 15), мили на A3
 *  (67,31) (2 → 18, пришли семеро), стрелок на A3 (31,67) (2 → 12). Это хранители.
 *
 *  Условия ухода хранителя сейчас — ранение, угроза урона и «его вооружённых в KEEP_RANGE больше KEEP_PICKET».
 *  Проверки «рядом ли своя группа» нет вовсе, и против кулака последнее условие срабатывает ровно тогда, когда
 *  уходить поздно. Правило оператора от 22.09.2026 называет это прямо: «не нужно до последнего стоять на флаге и
 *  терять боевые части — нужно отходить и возвращаться группой, способной отбить флаг». Флаг остаётся нашим после
 *  схода, так что хранитель против кулака только откладывает перезахват на время, которое стоит ему жизни.
 *
 *  Правка: пока его армия — один кулак (`Signals.enemyFistNow`, измеренное состояние, не имя соперника), хранитель
 *  снимается, как только медиана ядра дальше FIST_RADIUS + STRAGGLER_SLACK — того же радиуса, которым кулак v490
 *  определяет отставшего. Против рассыпанного соперника (рейдеры поодиночке) хранитель остаётся: там клетка под
 *  телом действительно не даёт перезахвата. Новых чисел нет. Прибор `kaway=`.
 *  ⚠️ ОТВЕРГНУТО СВОИМ ПРИБОРОМ (v565, 12 рук против けろびー#22: 0-12 против 2-10 у v564). Хранители уходят
 *  (`kaway` 74–544 за игру), но тел это НЕ сберегло — 5,8 в конце против 6,5, — а наш счёт упал почти вдвое: 4 476
 *  против 8 220, разрыв 14 764 против 10 106. Армия перезахватывает впятеро чаще (`cap3` 51 против 11), то есть
 *  флаги у нас не держатся. Посылка «хранитель против кулака только откладывает перезахват» неверна: тело на клетке
 *  заставляет его ПРИЙТИ И УБИТЬ, а без тела он переворачивает флаг мимоходом, не тратя ни тика и ни тела. Смерти
 *  хранителей, найденные реплеем, — цена удержания, которое окупается. Чтобы правило заработало, должно стать
 *  верным: уход хранителя сберегает тела (в конце больше, чем у v564) при не упавшем счёте. */
internal const val USE_KEEPER_STAYS_WITH_GROUP = false

/** УКЛОНЕНИЕ ОТ ТОГО, КТО НЕ ПОДХОДИТ, НЕ ЗАПИРАЕТ РАЗМЕНА ПРИ ПРОИГРАННОЙ ГОНКЕ (v566, см. Posture.decide,
 *  USE_ENGAGE_WHEN_RACE_LOST).
 *
 *  v564 (удар v563 + сбережённые тела) дала 2-10, лучший блок против けろびー#22. Две её победы и десять поражений
 *  разводит одно: КОГДА случился бой. В победе 2045 наши разгромили десять его тел на t≈600–700 (14 → 4), пока он
 *  держал большинство флагов (темп 3:18), — задолго до срока — и дальше взяли всё (21:0). В поражении 2040 с t=700
 *  до t=1400, 700 тиков, обе армии стоят: наших 8, его 13, темп 5:20, постура `EVADE`, `engage` не растёт. Строка
 *  постуры все эти тики одна и та же: `near=true contact=false approach=0 obj=- behind=true/873` — он рядом, НЕ
 *  подходит, брать нечего, мы позади. Армия уклоняется от армии, которая никуда не идёт.
 *
 *  Срок при этом жёсткий и считается из правил арены: матч кончается, когда отрыв больше 25 × оставшихся тиков. При
 *  его темпе 20 против наших 5 и отрыве 2 420 на t=700 это наступает около t≈1400 — ровно там поражение и кончилось.
 *  Уклонение от запаркованной армии, таким образом, не сберегает ничего, кроме тел, которые проиграют по очкам.
 *
 *  Правило размена v538 запирается `!pre.withdrawing`, то есть уклоняющаяся армия его не начинает никогда. Уклонение
 *  — ответ на армию, которая ИДЁТ на нас (`Signals.approachingNow`: темп сближения, сомкнутость, сдвиг его центра);
 *  от неподходящей оно ничего не выигрывает. Правка: при `EVADE` и неподходящем противнике запора нет. Отступление
 *  (`RETREAT`) не тронуто — это уход из боя, который проигрывается. Размен перебивает уклонение уже существующим
 *  путём: `fightNow` → режим FIGHT → постура ANNIHILATE. Новых чисел нет. Прибор `engidle=`. */
internal const val USE_ENGAGE_OVER_IDLE_EVADE = false
// ⚠️ ОТВЕРГНУТО (v566: 0-12; и в связке с v568–v570 — ещё 0-36). Уклонение сменилось постурой ANNIHILATE, но
// выигранных боёв не прибавилось: его армия в конце 8–13 тел во всех играх. Он от боя уходит, а погоня в хвост
// растягивает нашу армию на тех же одиночек (см. USE_FLEE_TO_GROUP).

/** ПРИ НАСТУПЛЕНИИ ВРАГА ХРАНИТЕЛЬ ОТХОДИТ К СВОИМ, ПОКА ЕЩЁ УСПЕВАЕТ (v567, правило оператора 22.09.2026, см.
 *  updateKeepers).
 *
 *  Оператор: «не обязательно крип должен сидеть на флаге и терять части от чужой армии — при наступлении врага он
 *  может убегать к своим и затем вместе с группой нападать».
 *
 *  Это поправка к отвергнутой v565, и она объясняет её провал. v565 снимала хранителя, когда уходила ГРУППА, — даже
 *  если враг никуда не шёл, — и он переворачивал флаги мимоходом: счёт упал почти вдвое, тел не сбережено. Здесь
 *  пусковое условие другое — НАСТУПЛЕНИЕ врага:
 *  - стоящий враг (`stationary`, запаркованный или гарнизон) ухода не вызывает — флаг держится телом, и ему, чтобы
 *    перезахватить, надо прийти и убить;
 *  - идущие вооружённые, которые хранителя перебивают по той же мере мощи (`enemyPowerOf` против `ourPowerOf`), —
 *    вызывают, как только они ближе, чем «расстояние до медианы своих + FIST_RADIUS + STRAGGLER_SLACK»: скорость у
 *    всех одна (MOVE — половина любого тела), и позже до группы уже не дойти. Одиночный рейдер хранителя не сгоняет.
 *  Хранитель, уже стоящий в радиусе своих, не уходит: его и так прикрывают.
