 *  Куда он идёт — к своим, а не прочь: снятый хранитель становится членом армии, кулак на каждый шаг (v564)
 *  отменяет шаги от медианы и оставляет только возвращение, а поводок ведёт к центру вооружённых. Дальше его
 *  преследователи входят в нашу группу, где настоящий бой мы выигрываем в 17 случаях из 23.
 *
 *  Основание по реплею 6ab2a493: хранители гибли, когда группа была в 12–18 клетках, а его кулак подходил за
 *  ~20 тиков — прежние условия ухода (ранение, угроза урона, KEEP_PICKET в KEEP_RANGE) срабатывали, когда уйти было
 *  уже поздно. Новых чисел нет. Прибор `kback=`. */
internal const val USE_KEEPER_FALLS_BACK_ON_ADVANCE = true

/** РАЗМЕН, НАЧАТЫЙ ПРИ ПРОИГРАННОЙ ГОНКЕ, — ЭТО НАТИСК (v568, см. StrategyPush.pushRaw, USE_ENGAGE_WHEN_RACE_LOST).
