 *  натиск сам по себе, мимо порогов мощи. Меру мощи правка не трогает. Новых чисел нет. Прибор `pusheng=`. */
internal const val USE_PUSH_WHEN_ENGAGED = false
// ⚠️ ОТВЕРГНУТО (v568: 0-12, `pusheng` 460–773 тиков за игру — натиск включался, боя не было: командир держал строй
// вне досягаемости). См. USE_MARCH_INTO_ENGAGE.

/** НАЧАТЫЙ РАЗМЕН ВНЕ КОНТАКТА ВЕДЁТСЯ МАРШЕМ НА ЕГО АРМИЮ (v569, см. Commander, commandMarch).
 *
 *  v568 включила натиск по начатому размену (`pusheng` 460–773 тиков за игру, постура ANNIHILATE 54–100 % второй
