 *  выбирает лучший прогоном, а прогон оценивает любой шаг внутрь как «первым получить залп». Кто шагнёт первым,
 *  тот первым и получит — оба бота этого избегают, а ничья по огню — это победа того, кто держит флаги.
 *
 *  Правка: когда размен начат (`Signals.engagingGarrison`), а контакта ещё нет, командир не раздаёт боевых клеток,
 *  а ведёт ядро МАРШЕМ (`commandMarch` — колонной, с лекарями, шаг в тик по полю) к его ближайшему вооружённому. С
 *  контактом включается обычная боевая раздача. Первый залп мы принимаем сознательно: настоящие бои против него
 *  мы выигрываем в 17 случаях из 23, а стояние вне досягаемости при проигранной гонке проигрывает всегда. Новых
 *  чисел нет. Прибор `engmarch=`. */
internal const val USE_MARCH_INTO_ENGAGE = false
// ⚠️ ОТВЕРГНУТО (v569–v570: 0-12; `engmarch` до 184 тиков за игру). Армии сошлись и перестали стоять — и выяснилось,
// что он от боя УХОДИТ: мы в 4 клетках — он в 8, и так весь матч, в конце у него 8–13 тел. Погоня в хвост при
// равной скорости не догоняет, а растягивает. Разбор 33 смертей в пяти поражениях: все 33 — в одиночку (своих в 5
// клетках 0–1), прижатых к стене или краю 4, стоявших 3; жертвы шли почти полным ходом (5–18 клеток за 20 тиков),
// и большая часть — ПРОЧЬ ОТ СВОИХ, в угол (лекарь t=906: до своих 44 -> 62, погиб в (94,92)).
//
// БЕГСТВО К СВОИМ (v571, правило оператора 22.09.2026, см. fleeToGroup). Оператор: «при наступлении врага он
// может убегать к своим и затем вместе с группой нападать». Бегство в коде было «как можно дальше от врага», и когда
// своя группа по ту сторону от него, оно уводило от своих — в угол, где его добирают (оператор: «карта не
// бесконечная, у неё есть стены»). Правка: крип дальше FIST_RADIUS + STRAGGLER_SLACK от центра своих вооружённых
// бежит путём к нему по карте опасности; прежнее бегство — запасное, когда пути к своим нет. Гарнизонный бегун,
// отступающий на шаг из-под выстрела и возвращающийся, не тронут. Новых чисел нет. Прибор `fgrp=`.
internal const val USE_FLEE_TO_GROUP = true

/** КОЛОННА НЕ РАСПУСКАЕТСЯ, ПОКА ЕГО АРМИЯ — ОДИН КУЛАК (v572, см. Commander, commandMarch, MARCH_SAFE).
