 *  150 тиков): он ПРИХОДИТ отбивать в 68 % (597), флаг теряется в 52 %, и в 70 % своих приходов он не теряет ни одного
 *  тела. Приманка работает, ловушка не захлопывается: группа при его подходе уходит. Постура в момент его прихода и
 *  судьба флага: EVADE 207 (потерян 62 %), FLAG — ушли за другим флагом — 159 (65 %), ANNIHILATE — погоня — 101
 *  (74 %), RETREAT 74 (69 %), и только HOLD — 56 (50 %).
 *
 *  Защита флага в боте написана: точка стояния `post` — наш флаг, у которого стоит группа, когда враг рядом. Но
 *  строка HOLD — ПОСЛЕДНЯЯ в таблице постур, под annihilate/flag/evade/retreat, и «стоит у флага» засчитывалось лишь
 *  в POST_STANDOFF (2) клетках. Правка: пока его армия — один кулак и его вооружённые рядом, а наш флаг в радиусе
 *  «со своими» (FIST_RADIUS + STRAGGLER_SLACK) от центра группы, строка `defend` идёт первой и даёт HOLD; точка
 *  стояния и марш командира в гонке — тот же флаг (`defendedFlag`, одно решение на трёх читателей). Под огнём бой
 *  подхватывает боевой режим обычным путём. Новых чисел нет. Прибор `defend=`. */
internal const val USE_DEFEND_HELD_FLAG = false
