/** ПРОТИВ ОБЪЕЗДЧИКА ФЛАГ БЕРЁТ ГРУППА, КОТОРАЯ ЕГО И ДЕРЖИТ (v574, строка `tourer` ворот захвата).
 *
 *  Он побеждает тем, что переворачивает флаги: объезжает их одной группой и берёт каждый, на который наступил. Мы
 *  берём мало — 8–11 захватов армией за игру, — потому что ворота отказывают: `cap3why` — паритет 58 %, дебют (rush,
 *  first.fight) ещё 34 %. Паритет бережёт армию от дебаффа в бою, который она проиграет. Против этого соперника
 *  такой бой редок: настоящих схваток 23 на ~60 игр, 17 выиграли мы, и в 70 % его приходов к нашему флагу он не
 *  теряет ни тела. Строка `groupSafe` (v336, «паритет не сторож против того, кто не бьёт наших в группе») уже есть —
 *  и заперта `!foughtFoe`: мера `cannotWipeUs` считает, что он стирает нас за 477–555 тиков, по ТЕМПУ ПОТЕРИ ТЕЛ,
 *  то есть по одиночкам (`unwipe` 841 из 3 041 вопросов). Каскад замыкается: гибнут одиночки -> мера зовёт его
 *  бойцом -> паритет запрещает флаги -> он обыгрывает по очкам.
 *
 *  Правка берёт то же основание, что `groupSafe`, но спрашивает о ГРУППЕ, а не о прошлом уроне: пока его армия —
 *  один кулак, его вооружённых нет в ENGAGE_RANGE от флага, а центр нашей группы в радиусе «со своими» от флага,
 *  захват разрешён до всех вето. Бой у этого флага, если он придёт, будет с нашей группой, которая его держит
 *  (v573), — а такие бои мы выигрываем в трёх случаях из четырёх. Бегун вдали от группы через строку не проходит.
 *  Новых чисел нет. Прибор `tour=`. */
internal const val USE_TOUR_CAPTURE_VS_FIST = true

/** СКАУТ ПРЯЧЕТСЯ В БОЛОТЕ, А НЕ БЕЖИТ В УГОЛ (v575, `refugeMove`, ветка REFUGE бегуна).
 *
 *  Разбор 13 реплеев против けろびー#22 (субагент Opus, 23.09.2026): ОДИНОЧКА ДЛЯ НЕГО ВАЖНЕЕ ФЛАГОВ. Изолированный наш крип
 *  тянет его вооружённых со всей карты: в дебюте за нашим скаутом идёт вся армия (в 15 клетках от скаута 5–10 его крипов,
 *  до 12), флагов он не берёт, пока скаут жив (раньше t=186 — ни разу), и первый его флаг — ближайший к месту гибели
 *  последнего скаута, через 4–18 тиков после неё (7 матчей из 13). После t=260 до 70 % его вооружённых идут к одиночке и
 *  с 40–60 клеток. Наши скауты гибнут на t=93–159 и 169–651, и 22 погони из 24 длиннее 20 тиков кончились в 3–9 клетках от
 *  края: жадное бегство «прочь» уводит в угол, где клеток нет.
 *
 *  Что должно быть верно, чтобы скаута не догнали вовсе: ему нужна клетка, куда не достаёт выстрел с равнины и куда его
 *  боевые тела входят впятеро медленнее. Это болото глубже дальности выстрела: скаут (одни MOVE) идёт по нему клеткой за
 *  тик, его боевое тело (половина MOVE) — клеткой за пять. На каждой карте четыре болота по 80–115 клеток и 12–30 клеток
 *  такой глубины. Поэтому скаут — ПОСТОЯННАЯ ПРИМАНКА: с первого тика он идёт в своё убежище (самое далёкое от флагов, при
 *  равных — ближе к нашему дому; i-й скаут — i-е) и живёт там, флагов паросочетанием не берёт; не успевает в своё — в
 *  любое, до которого ближе всех его стволов. Пока скаут жив и одинок, его армия, по разбору, ходит за ним, а не за
 *  флагами, — и флаги берёт наша группа. Глубина и запас вычислены из правил: REFUGE_DEPTH = дальность выстрела + 1,
 *  REFUGE_SLACK = по шагу каждой стороны за тик решения. Прибор `refuge=` (go / run / stay / dodge / late), `rfcells=`.
 *  ⚠️ ОТВЕРГНУТО ЖИВЫМ ЗАМЕРОМ (23.09.2026, матч 6ab30b7e): он ИДЁТ в болото за одиночкой. Три стрелка и три лекаря вошли
 *  в болото по клетке за пять тиков (усталость 48 -> 0, как по правилам) и за 12 тиков встали в трёх клетках от скаутов;
 *  убежище той карты — четыре клетки глубины 4, двое скаутов мешали друг другу, оба погибли на t=73–74 — раньше обычного
 *  (93–159). И сразу подтвердилась посылка разбора: свой первый флаг он взял на t=109, в 35 тиках после гибели скаутов, —
 *  во всех 13 прежних реплеях не раньше t=186. Что должно быть верно, чтобы убежище работало: болото глубже, чем он готов
 *  пройти по клетке за пять тиков, — на этих картах таких нет. Рычаг — ВРЕМЯ ЖИЗНИ скаута, см. USE_SCOUT_MARGIN_EVADE. */
internal const val USE_SCOUT_SWAMP_REFUGE = false

/** Глубина убежища: клетка болота, от которой до равнины не меньше дальности выстрела + 1 (см. USE_SCOUT_SWAMP_REFUGE). */
internal const val REFUGE_DEPTH = RANGED_RANGE + 1

/** Запас хода к убежищу: решение принимается по позициям начала тика, а за тик шагают обе стороны (см. refugeMove). */
internal const val REFUGE_SLACK = 2

/** СКАУТ ЖИВЁТ ДОЛЬШЕ: УКЛОНЕНИЕ ПО ЗАПАСУ ВРЕМЕНИ (v576, `ScoutEvade`, ветка EVADE бегуна).
 *
 *  Посылка — тот же разбор 13 реплеев (см. USE_SCOUT_SWAMP_REFUGE) и её живое подтверждение в матче 6ab30b7e: пока наш
 *  скаут жив и одинок, его армия ходит за ним и флагов не берёт; первый его флаг — в 4–35 тиках после гибели последнего
 *  скаута. Значит, каждый тик жизни скаута — тик, когда он не фермит, а наша группа берёт флаги. Скауты гибли, потому что
 *  бегство знало только «прочь от ближайшего» и уводило в угол (22 погони из 24), а убежище — потому что он входит в болото.
 *
 *  Что должно быть верно, чтобы скаута не догнали: скаут стоит там, куда дойдёт раньше, чем его достанет выстрел. Это
 *  классическая область преследуемого: время его стволов до клетки (равнина — тик, болото — SWAMP_COST, плюс дальность
 *  выстрела) минус время скаута (тик везде). Скаут идёт в клетку с наибольшим запасом; болото, где его тела вязнут, даёт
 *  запас само, угол, куда он подходит с открытой стороны, — нет. Флаг скаут берёт, только если успевает на него с запасом
 *  SCOUT_FLAG_MARGIN, и держит свой, пока запас на нём не меньше. Числа вычислены из правил. Прибор `scev=`.
 *  ➖ ЗАМЕР v576 (0-10 против けろびー#22): на t=400 мы вели во всех десяти руках (2 460–4 868 против 752–1 777 — скауты
 *  живут до t=107–763 вместо 73–104 и берут флаги), а проигрыш набран в середине игры. Скауты гибли в углах: цель
