/** ПРОТИВ ОХОТНИКА ЗА ОДИНОЧКАМИ НИКТО ИЗ АРМИИ НЕ ОСТАЁТСЯ ОДИН (v579, `Signals.lonerHunted`).
 *
 *  Разбор 13 реплеев против けろびー#22: 66 наших смертей из 73 — одиночки (в шести клетках не больше одного своего), бьют
 *  их в среднем четверо, подходя с 18 клеток; минимальная безопасная единица — четыре крипа. В блоках v575–v577 одиночных
 *  смертей 28 на пять матчей: хранитель у флага 12, отряжённый к флагу 8, вдали 7. Выпуск и хранитель закрыты сейчас только
 *  при его кулаке (`enemyFistNow`, v553, v565), а после t=250 его армия раздроблена на три куска и больше в 48 % тиков —
 *  тогда наши выходят, и их добивают. В матче v577 6ab31365 он не потерял ни одного крипа, а мы за 800 тиков — все.
 *
 *  Что должно быть верно, чтобы одиночек не было вовсе: никто из армии не отходит от неё. Признак берётся из самой
 *  игры: наш боевой погиб, стоя с не больше чем одним своим в радиусе «со своими», и у его клетки трое его и больше. С
 *  этого тика до конца матча армия никого не выпускает (оба пути выпуска — бюджет гонки и отряд стратега), а хранитель
 *  уходит вместе с группой. Против того, кто одиночек не ловит (фермеры), признак не срабатывает, и отряды остаются.
 *  Флаги вдали берут скауты (v576). Прибор `lonerhunt=` — тик срабатывания. Новых чисел нет. */
internal const val USE_NO_LONERS_VS_HUNTER = true
// ⚠️ ПЕРЕОТКРЫТО (v586, 23.09.2026): одиночек после признака нет (руки v581–v584: тела 9–11 до конца), но нет и боёв — с v575
// он почти не теряет крипов, и все блоки v575–v585 проиграны (0 из ~60) против 2 из 23 у v564. Во всех наших победах над ним
// (v556–v572 и старые реплеи) он терял 5–10 крипов в одном бою, когда его куски входили в нашу стоящую группу — идя к
// своим лекарям или за нашими одиночками. Правило снято на замер: одиночки как приманка против отсутствия боя.

/** ЕГО ОДИНОКИЕ ЛЕКАРИ — ЦЕЛЬ МАРША АРМИИ (v580, `loneHealerGoal`, марш командира в гонке).
 *
 *  Во всех матчах блоков v575–v577 против けろびー#22 он не потерял НИ ОДНОГО крипа: мы не убиваем ничего, а его кулак из
 *  двенадцати в конце добивает наш остаток. Разбор 13 реплеев: его лекари дальше восьми клеток от всех его вооружённых в
 *  27 % тиков; в матче v576 6ab30e75 три его лекаря стояли одни в девяти клетках от нашей группы из десяти 450 тиков.
 *  Ветка тактика `raider` (его безоружный на нашей половине) там была истинна 94 тика и не выиграла ни разу: крипа вёл
 *  приказ марша командира, а цель марша — флаг.
 *
 *  Что должно быть верно, чтобы лекари не жили: армия идёт на них, пока никто из его вооружённых не успеет к ним раньше
 *  нас. Условия вычислены из игры: его крип только с лечением, его вооружённых нет в ENGAGE_RANGE от него, он не уходит
 *  (`catchable` — та же мера, что у погони и охоты), и центр нашей армии к нему ближе, чем любой его вооружённый. Тогда
 *  цель марша — лекарь, а не флаг; бой у цели подхватывает обычный путь. Лекарь не бьёт, поэтому марш ничем не рискует,
 *  кроме флага, от которого уходим. Новых чисел нет. Прибор `healhunt=`. */
internal const val USE_MARCH_ON_LONE_HEALERS = false
// ⚠️ ОТВЕРГНУТО ЖИВЫМ ЗАМЕРОМ (v584, 23.09.2026): в первой руке v583 (6ab31b6e) марш на его лекарей шёл 577 тиков и не
// догнал ни одного: они держались в 5–10 клетках от армии, не уходя (`catchable` их пропускает), а армия ходила за ними
// у Aa и Ha. На t=400 мы вели 4 647 : 846 при флагах 6:1, на t=600 — 8 139 : 2 354; к t=700 он взял все семь, и наш счёт
// стоял на 8 302 с t=800 до конца. В руках v580–v582 два-четыре его лекаря убиты, но ни одна рука не выиграна. Что должно
// быть верно, чтобы марш окупался: лекаря можно догнать — а он стоит ровно вне досягаемости, как и всё его войско.

/** ПРОТИВ ОХОТНИКА ЗА ОДИНОЧКАМИ ХРАНИТЕЛЕЙ ИЗ АРМИИ НЕТ (v581, `updateKeepers`, признак `Signals.lonerHunted` из v579).
 *
 *  В двух руках v580 после срабатывания признака (t=444 и t=107) отзывать было некого (`lonerhunt=…/0`), а одиночки гибли
 *  дальше — все у флагов: D5, Aa, Ha, (92,16), (51,51), (67,31), тринадцать смертей на две руки. Уход хранителя с группой
 *  (v565) срабатывал (`kaway` 164 -> 333), но армейский крип снова вставал на флаг, снова становился хранителем и гиб в
 *  промежутке: группа ещё в шести клетках, а он уже подходит. Что должно быть верно, чтобы одиночки у флагов не было:
 *  хранителя из армии нет вовсе. Флаг остаётся нашим после схода с клетки, пока он сам на него не встанет; держать флаг
 *  телом — работа скаута. Прибор `nokeep=`. Новых чисел нет. */
internal const val USE_NO_KEEPERS_VS_HUNTER = true
// ⚠️ ПЕРЕОТКРЫТО вместе с USE_NO_LONERS_VS_HUNTER (v586) — без признака правило и так не действует.

/** ОТСТАЁМ ДОЛЬШЕ ТЕРПЕНИЯ И СИЛЬНЕЕ ЕГО — НАТИСК И БЕЗ РАЗМЕНА (v582, `pushBehind` в StrategyPush).
 *
 *  Первая рука v581 против けろびー#22 (6ab31806): армия цела — девять тел с t=600 до конца, ни одной смерти после признака
 *  охоты, — а очки уходят: с t=550 обе армии стоят у D5 в семи-восьми клетках, флаг переходит из рук в руки каждые 12 тиков,
 *  он держит остальные шесть и берёт 25 в тик против наших 0–5 (6 620 : 3 218 на t=600 -> 7 330 : 22 458). По нашей же
 *  мере мы сильнее: 2 179 против 1 469–1 688 (его шесть флагов режут ему атаку и выстрел до ×0,6, лечение до ×0,5), постура
 *  ANNIHILATE, `behind` 420 тиков — и `pushing=false`: натиск по мощи требует идущего размена (`exchangePaying`) и не
 *  простоя, а размена нет, пока не стреляет никто. Разбор 13 реплеев: все четыре крупных наших боя выиграны, когда он держал
 *  4–7 флагов (его потери 10, 11, 6, 5; наши 0–2).
 *
 *  Что должно быть верно, чтобы стояния не было: сильнейший идёт на слабейшего, когда стояние ему в убыток. Условия — уже
 *  существующие меры: отставание по прогнозу дольше BEHIND_PATIENCE (порог натиска тогда уже понижен до
 *  PUSH_RATIO_STALEMATE), наша мощь против его ударной пачки не ниже этого порога, есть ударные. Отступит — флаг наш, не
 *  отступит — бой, который мы по своей мере выигрываем. Новых чисел нет. Прибор `pushbeh=`. */
internal const val USE_PUSH_WHEN_BEHIND_AND_STRONGER = false

/** ОСПАРИВАЕМЫЙ ФЛАГ — ПОСЛЕДНИМ, И СВОЮ ПОЛОВИНУ ОН НЕ ДЕРЖИТ (v583, `contestedFlag` в chooseFlagObjective).
 *
 *  Руки v581–v582 против けろびー#22: армия цела (9–11 тел до конца), а с t=550 обе армии стоят у D5 в семи клетках, флаг
 *  переходит из рук в руки каждые 12 тиков, он держит остальные шесть и берёт 25 в тик. Цель армии всё это время — D5, и
 *  по двум правилам режима пар (`groupSafe` — он не бьёт наших в группе): стая у флага цели не отменяет (v304), а флаги его
 *  половины отбрасываются как «далёкие», пока своя половина не наша (v312, `objdrop far` 960 -> 2 052 за двести тиков).
 *  D5 посередине считается нашей половиной и не бывает нашим дольше 12 тиков — замок до конца матча.
 *
 *  Что должно быть верно, чтобы замка не было: флаг, который он перебьёт, едва наш крип сойдёт с клетки, не стоит похода,
 *  пока есть флаг, который он перебить не может. Под `groupSafe` флаг, у которого его вооружённые стоят в ENGAGE_RANGE,
 *  выбирается целью только при отсутствии других, и свою половину не держит. Вне режима пар (гарнизоны, блоки) выбор
 *  прежний. Новых чисел нет. Прибор `objcont=`. */
internal const val USE_CONTESTED_FLAG_LAST = true

/** СКАУТ-ПРИМАНКА БЕЖИТ К СВОИМ, КОГДА ОН ИДЁТ (v585, `ScoutEvade.move`, ветка `home`; правило оператора 22.09.2026).
 *
 *  Две приманки v576–v584 делают своё: пока одинокий скаут жив, его армия ходит за ним, и на t=400 мы ведём
 *  (3 707–4 647 против 831–1 500). Но скауты гибнут в углу с нашей базой на t=216–646: клетка, которую он обстреляет позже
 *  всех, — этот угол, а из угла, когда он подходит со стороны выхода, выхода нет. Через 13 тиков после их гибели в
 *  руках v584 его одиночки начинают перебивать наши флаги за спиной группы — наших одиночек, способных перебить в ответ,
 *  нет.
 *
 *  Что должно быть верно, чтобы скаут был и приманкой, и жив: он уводит его армию вдаль, а когда та подходит, уходит к
 *  своим, пока путь открыт (к группе из четырёх и больше он не подходит ближе пяти-семи клеток). Порог из тех же двух
 *  полей: срок обстрела клетки скаута не больше двойного пути по его области до клетки в радиусе кулака от центра армии
 *  плюс запас. Новых чисел нет. Прибор `scev=home`. */
internal const val USE_SCOUT_RUNS_HOME = false

/** ПРИМАНКА ПРОТИВ ОСЛАБЛЕННОГО (v587, `Signals.baitPhase`, ворота захвата `bait`, ветка командира `commandBait`).
 *
 *  Разбор 55 игр против けろびー#22 (три субагента Opus, 23.09.2026). Размен решает разница дебаффов: пока мы держим 2–5
 *  флагов, а он 0–3, его смертей на одну нашу 0,02–0,17; при наших 0–1 и его 6–7 наша собранная группа из 3+ в строю не
 *  гибнет вовсе (22 его атаки: у него 20 смертей, у нас ноль в строю). Сам он при этом нападает редко — в 9 % подходов, а
 *  при его перевесе по числу 1,8 и больше — в 29 %, и эти атаки дали 11:0 в нашу пользу. Оба разгрома его армии (6ab2af3c:
 *  0:6, 6ab32882: 0:7, в матче 10:0) — атаки на нашу группу из 6–7 с тремя лекарями при его перевесе 1,7–2,0 и всех его
 *  флагах; вторая дала победу 22 598 : 16 418 из 4 835 : 7 306.
 *
 *  Что должно быть верно, чтобы разгром был не случайностью: он держит все флаги, кроме одного (сам под полными
 *  дебаффами), мы не держим больше одного (без дебаффа), а перед ним — группа вдвое меньше его армии. Поэтому в этой фазе
 *  флагов не берём (ворота `bait`), а армия делится пополам — лекари поровну: приманка стоит, резерв стоит в MASS_RANGE +
 *  FIST_RADIUS клетках дальше от его кулака, за радиусом, в котором он считает наших у цели. При контакте бой ведёт
 *  обычный режим всей армией. Фаза — когда у обоих хватает бойцов на кулак и на две половины по BAIT_MIN. Чтобы к фазе
 *  было кем делиться, запрет одиночек после его охоты (v579–v581) снова включён. Прибор `bait=` (вёл / фаза). Отдельный
 *  отряд-приманка в данных встречался 16 раз — доктрина проверяется этим замером. */
internal const val USE_BAIT_VS_DEBUFFED = false
// ⚠️ ОТВЕРГНУТО ЖИВЫМ ЗАМЕРОМ (v593, 23.09.2026): v587–v592, по руке-две на редакцию, — 0 побед; механика заработала только
// к v592 и показала, что посылка неверна. v588: фаза 817 тиков, армия стояла там, где была, в 22 клетках от него; v590:
// приманка в восьми клетках от его кулака 808 тиков — он припаркован на D5, брать ему нечего, не идёт; v591: приманка
// взяла Ab, но резерв встал в 8–9 клетках — у флага он видел одиннадцать; v592 (6ab3369e): приманка из шести держит D5,
// резерв в 16 клетках, его куски стоят вокруг в 8–12 клетках 600 тиков при перевесе ~2 и шести своих флагах — и не
// атакуют. Разгром 6ab32882 был стечением: наша группа бежала в угол, и он пошёл за ней; как правило его поведения он не
// повторяется. Что должно быть верно, чтобы приманка работала: он нападает на слабую группу, когда сам под дебаффами, —
// а при наших 0–1 флагах и его 6–7 он в 9 % подходов нападает и в остальных ждёт.

/** Половина армии в приманке — не меньше этого: группа, которую он атаковал и проиграл, была из 5–7 (разбор 55 игр). */
internal const val BAIT_MIN = 5

/** ПРИМАНКА НА ХОДУ (v598, `commandMovingBait`, фаза `Signals.baitPhase`, ворота захвата `bait`, ступень тактика `baitHold`).
 *
 *  Разбор 81 реплея против けろびー#22 (субагент Opus, 23.09.2026; 2110 сближений его куска с нашей группой на 12 клеток,
 *  96 нападений) нашёл его правило нападения, и приманка v587–v592 нарушала его в главном:
 *  - он бьёт ДВИЖУЩУЮСЯ группу: стоявшая оба окна по 10 тиков атакована 1 раз из 503, движущаяся — 84 из 1334, а при
 *    перевесе его куска 1,4+ — 36 из 233 (15,5 %); движение в прошлом окне предсказывает нападение тоже — это не наша
 *    реакция на его подход. Приманка v592 СТОЯЛА на D5: 345 сближений, 223 со стоящей группой, нападение одно;
 *  - мерило — вся его армия против нашей группы (AUC 0,78 на радиусе 6 против 0,70 на 30), порог около BAIT_RATIO; наших
 *    дальше ~10 клеток он не считает (вес поддержки в 16–25 клетках в регрессии ноль);
 *  - своих дебаффов он не учитывает: при его 5–7 флагах доля нападений та же (14,9 % против 14,6 % при 3–4), а размен при
 *    разнице флагов 6–7 — 1,22 его тела против 0,22 наших на нападение (при 4–5 — 0,52 против 0,91). Все шесть разгромов
 *    его армии (он терял 4–9, мы 0) — нападения на ДВИЖУЩУЮСЯ группу из 5–8 с 2–3 лекарями без наших рядом при его 4–7 флагах.
 *
 *  Что должно быть верно, чтобы разгром стал правилом: в фазе, где он держит все флаги, кроме одного, перед ним ходит группа,
 *  малая против его армии, с нашими тремя лекарями, а остальные стоят вне его счёта. Приманка v598 — лекари, мили, стрелки по
 *  порядку, BAIT_MIN и больше, пока его армия видит перевес BAIT_RATIO; ходит поперёк направления на него в BAIT_STANDOFF
 *  клетках; резерв стоит в MASS_RANGE–BAIT_LEASH позади. Контакт — обычный бой всей армией. Прибор `mbait=`, `bait=`.
 *  ➖ ЗАМЕР v598 (0-8, разбор 8 реплеев субагентом Opus): фаза открывалась с t=250–500 во всех восьми, приманка ходила как
 *  задумано (3–12 клеток за 10 тиков в 70 % окон), правило его подтвердилось (при посылке «движется, перевес ≥1,8» — 4
 *  нападения из 12 при прогнозе около двух), но разгромов ноль: пара «приманка ходит / резерв стоит» разошлась больше чем на
 *  6 клеток в 11 окнах из 278, в 10 клетках от центра приманки — 10 наших. Центр патруля отсчитывался от РЕЗЕРВА, а резерв
 *  стоял, где застала фаза, — в 12 клетках от него: `k` упирался в MASS_RANGE, приманку слало в 4–9 клеток от него и в
 *  6–8 от резерва. В контакте подходили мы (37 эпизодов против его 16): режим боя двигал всю армию, и он уходил (−4,6…−8,8
 *  клетки, потери 0/0). В двух из пяти атакованных приманок не было стрелка — он перестреливал нас 1 010 ударов против 370.
 *  Очки в фазе: мы +8,3 тыс., он +102 тыс. Что должно быть верно (v599): приманка видна ОТДЕЛЬНО — резерв сперва отходит
 *  не ближе BAIT_STANDOFF + MASS_RANGE + 2 от центра его крупнейшей группы (не от ближайшего: его одиночки держатся в 5–7 от
 *  нас), и приманка не ближе MASS_RANGE + 2 к резерву; в приманке стрелок; в контакте приманки резерв стоит.
 *  ⚠️ ОТВЕРГНУТО ЖИВЫМ ЗАМЕРОМ (v600, 23.09.2026): блок v599 — 0-8, разгромов ноль. Фаза открывалась с t=300–580 во всех
 *  восьми и шла 300–940 тиков (раскладка `setup` 66–246 тиков), его армия к концу 10–14 из 14, наша 6–11; в трёх руках
 *  приманкой была вся армия (`all`: наших меньше BAIT_MIN + BAIT_RESERVE_MIN). За два блока — 0 из 16, и фаза, где армия не
 *  берёт флаги, отдаёт гонку: в v598 мы +8,3 тыс. очков в фазе, он +102 тыс. Правило его подтвердилось, но разгромы в
 *  данных — СТЕЧЕНИЕ, которое наша постановка не воспроизводит: приманку при посылке правила он атаковал в 4 из 12, и ни одно
 *  нападение разгромом не кончилось. Что должно быть верно, чтобы приманка окупилась: нападение кончается разгромом
 *  чаще, чем за фазу набегает его отрыв по очкам, — на наших 16 руках ни разу. */
internal const val USE_MOVING_BAIT = false

/** Перевес его армии над нашей группой, с которого он нападает (разбор 81 реплея: доля нападений по «вся его армия / наши в 6» —
 *  1,4–1,8: 6,8 %; 1,8–2,4: 16,2 %; от 2,4: 19,7 %). */
internal const val BAIT_RATIO = 1.8

/** Резерв меньше этого — одиночки и пары, на которых он охотится (минимальная безопасная единица — четыре, v579). */
internal const val BAIT_RESERVE_MIN = 4

/** Дистанция приманки до его ближайшего вооружённого: его кусок в 12–14 клетках в начале нападений (разбор 81 реплея). */
internal const val BAIT_STANDOFF = 13

/** Приманка не дальше этого от резерва: разбор — «не дальше 16–20 клеток по пути её отхода». */
internal const val BAIT_LEASH = 16

/** Полуотрезок патруля приманки: ход 3–12 клеток за 10 тиков у нападений; отрезок в 12 проходится за 12 тиков. */
internal const val BAIT_LEG = 6

/** Тиков без сдвига медианы приманки до разворота: стена или толкотня. */
internal const val BAIT_STUCK = 3

/** Терпение приманки: тиков приманки без контакта, после которых фаза закрыта до конца матча. Против けろびー#22 нападение
 *  на движущуюся малую группу — 16–22 % за 30 тиков манёвра (разбор 81 реплея), то есть за 300 тиков без контакта с его
 *  правилом оно случилось бы с вероятностью около 0,9; нет — это не он, и фаза, в которой армия флагов не берёт, только
 *  отдаёт очки: на стенде без выхода фаза шла 900–1000 тиков, и scatter m33 и blitz m31 проигрывали 3 883 и 2 953 при
 *  22 795 и 24 017 у v597. */
internal const val BAIT_PATIENCE = 300

/** Раскладка приманки (v599): тиков подряд, которые армия отходит, чтобы резерв встал не ближе BAIT_STANDOFF + MASS_RANGE + 2
 *  от него; он может идти следом, и отход без предела стал бы бегством. Двадцать тиков — двадцать клеток: вдвое больше
 *  MASS_RANGE + 2, на которые резерву нужно отодвинуться от приманки. */
internal const val BAIT_SETUP = 20

/** СТОЯЩИЕ ГАРНИЗОНЫ (v600, `Garrisons`, ступень шага тактика `garrison`, ветка бегуна GARRISON).
 *
 *  Разбор 81 реплея против けろびー#22 (k22a, 23.09.2026): СТОЯЩУЮ группу он не трогает. Группа, неподвижная два окна по
 *  10 тиков: 3–4 — 1 нападение из 33, потерь 0 из 33; 5–6 — 0 из 59; 7–8 — 0 из 117; 9+ — 0 из 294. Гарнизон 3–5 с лекарем
 *  на клетке флага или в клетке от неё — 1 нападение из 30, погибших за 60 тиков 0 из 30; простоявшая 150+ тиков — 0 из 302.
 *  Движущуюся малую группу он бьёт (при перевесе его армии 2,4+ — 19,7 % сближений), одиночек и пары на флаге добивает,
 *  стоят они или нет (за 60 тиков гибнет 24 %). Приманки v587–v599, которые ловили его на этом правиле, разгромов не дали.
 *
 *  Что должно быть верно, чтобы наши флаги были нашими: на каждом стоит группа, которая не шевелится. Бойцов двенадцать —
 *  три отряда по GARRISON_SIZE, по лекарю в каждом, на три самых дорогих флага: D5 и оба H — 13 очков в тик против его
 *  12 на A и R. Дебаффы при этом в нашу пользу в бою: у нас уязвимость ×1,1 и лечение ×0,5, у него атака и дальний удар
 *  ×0,6. Отряд идёт на пост по полю и стоит до конца матча; в бою бьёт с места. Прибор `gar=`.
 *  ➖ ЗАМЕР v600 (0-8): правило подтвердилось вчистую — в семи руках из восьми тела 8:12 с t=200 до конца матча, ни одной
 *  смерти ни с одной стороны за 800+ тиков, два наших гарнизона стояли на Ha и Hb. Но отряд D5 погибал на флаге во всех
 *  восьми, на t=44–105, от 9–12 его крипов: в дебюте он ведёт к D5 всю армию, обе армии идут туда ~40 тиков, и пришедшая
 *  четвёрка для него — движущаяся малая группа; флаги 2:5, счёт 8 против 17 в тик. И H-отряды стояли у своих флагов по 200+
 *  тиков: ворота захвата армии отказывали шагу на флаг, уже взятый его бегуном. v601: отряд оспариваемого флага (наименьшее
 *  «дальнее из двух расстояний до баз») ждёт на базе, пока его группа побывает у флага и уйдёт; боец гарнизона на флаг своего
 *  отряда идёт мимо ворот захвата.
 *  ➖ ЗАМЕР v601 (0-8, 4 руки дошли до t=1600): отряд D5 гиб всё равно — на базе, куда его армия пришла за скаутами (две
 *  руки), или у D5 после выхода (t=104–165, его 6–12 рядом); отбившийся вперёд мили H-отряда гиб один. И решающее: с
 *  t≈250–400 до конца матча его кучка из 9 СТОИТ на D5 во всех восьми разобранных руках (кучки 4+ в 26 клетках от D5 не было
 *  в 1 выборке из 48 на t=400–699 и в 0 из 56 на t=700–1000) — D5 его лагерь, туда не пройти. Остальные флаги держат его трое
 *  и скауты. v602: оспариваемый флаг не наш; четыре тройки — на четыре флага по цене, при равной — дальше от оспариваемого
 *  (Ha, Hb, Ra, Rb: 14 очков в тик против его 11); отряд идёт кучно.
 *  ⚠️ ОТВЕРГНУТО ЖИВЫМ ЗАМЕРОМ (v604, 23.09.2026): v602 (тройки) — 0-8, v603 (три четвёрки на Ha, Hb и ближнем R) — 0-8, при
 *  этом на t=400 мы вели в семи руках из восьми (до 4 614 : 786), на t=1000 — в двух, и матчи шли до t=1 300–1 731. Без
 *  отряда-жертвы на D5 гибли уже H-четвёрки — у своих флагов, на t=97–192, от его 10–12: стоящую четвёрку он не трогает,
 *  только УСТОЯВШУЮСЯ, а устояться она успевает, лишь пока его армия занята другим (в v600 — отрядом D5). Его первый флаг
 *  в v603 — t=115–323: всё начало его армия выбивала наши четвёрки, а не брала флаги. Что должно быть верно, чтобы
 *  гарнизоны выигрывали: четвёртый флаг вне его лагеря на D5 (бойцов на четвёртую четвёрку нет — 11 очков против 14 при
 *  любом раскладе) и время устояться до прихода его армии; ни того ни другого у нас нет. Код оставлен для сочетаний. */
internal const val USE_STANDING_GARRISONS = false

/** Размер стоящего гарнизона. Флагов вне его лагеря на D5, которые дают больше половины очков, — четыре (Ha, Hb и оба R:
 *  14 из 25), бойцов двенадцать, отсюда три. Цена названа: стоящую группу 3–4 разбор видел атакованной 1 раз из 33 при 0
 *  смертей (верхняя граница риска около 10 % на сближение), тройку отдельно — не мерил; одиночки и пары на флаге гибнут
 *  (v579). Четвёрки v600–v601 держали флаг до конца матча, но их три — 11 очков против его 14 (стенд v602 с четвёрками:
 *  три сценария проиграны 18,9 тыс. против 24,2 тыс.).
 *  ⚠️ ОТВЕРГНУТО ЖИВЫМ ЗАМЕРОМ (v603, 23.09.2026): блок v602 с тройками — 0-8, к t=400 от двенадцати бойцов у нас трое в
 *  семи руках из восьми: СТОЯЩИЕ тройки на Ha, Ra, Hb он бьёт всей армией (его 9–12 в 6 клетках, t=114–256), а четвёрки
 *  v600–v601 на тех же H-флагах стояли до конца матча нетронутыми. Граница его правила — четыре, не три. С v603 — четыре. */
internal const val GARRISON_SIZE = 4

/** СНЯТЬ ЛАГЕРЬ (v605, `Garrisons.campBreak`, прибор `camp=`; гарнизонный шаг `Garrisons.step`).
 *
 *  Арифметика v596–v604: стоящую УСТОЯВШУЮСЯ четвёрку он не трогает (v600: 800+ тиков без единой смерти с обеих сторон), но
 *  четвёрок у нас три, а D5 с t≈250–400 — его лагерь из девяти; без D5 лучший расклад — 11 очков в тик против его 14, и
 *  ранний отрыв (на t=400 — до +3 800) этого не покрывает. С D5 — иначе: D5 + H + ближний к H флаг — 12 против 13 (−1 500
 *  за полторы тысячи тиков, отрыв покрывает), D5 + оба H — 13 против 12. И устояться четвёрка успевает, только пока его армия
 *  занята другим (v603: без этого H-четвёрки гибли по приходе).
 *
 *  Что должно быть верно, чтобы D5 стал нашим: лагерь снят, и четвёрка на D5 устоялась раньше, чем он вернётся. Натиск
 *  всей армией — единственное, от чего он уходит (86 %), а группу из 8+ он почти не атакует (движущуюся — 2–5 %). Поэтому до
 *  лагеря армия играет как прежде (отрыв дебюта), а когда его CAMP_MIN боевых простоят у оспариваемого флага CAMP_TICKS
 *  тиков, армия делится на отряды по GARRISON_SIZE и идёт на флаг вся; первый отряд встаёт на флаг, остальные стоят рядом
 *  GARRISON_SETTLE тиков, пока он устаивается; дальше восьмёрка идёт на самый дорогой из прочих, второй отряд встаёт там под
 *  прикрытием третьего, и третий идёт на ближний ко второму флаг. Лагеря нет — этап 0 длится весь матч (прежнее поведение).
 *  ⚠️ ОТВЕРГНУТО ЖИВЫМ ЗАМЕРОМ (v612, 23.09.2026): v605–v611 — 0 из 56 (варианты старта, размера отрядов и ухода — в
 *  USE_EARLY_CAMP_BREAK, USE_PASSIVE_GATE, USE_LEAVE_WHEN_CLEAR, USE_HOLD_UNTIL_PASSIVE, USE_BLOB_UNTIL_PLAN). Натиск D5 берёт,
 *  устоявшиеся четвёрки на H стоят до конца без потерь, но ЧЕТВЁРКА НА D5 не держится ни при каком раскладе: её выбивают
 *  его 8–12 вскоре после ухода восьмёрки (v606, v609, v610, v611 — почти все руки), а когда армия ждёт у D5, пока его группа
 *  отойдёт, он стоит вплотную (его 12 в 13 клетках) до конца матча (v611 — четыре руки). В v607 D5 устоял лишь потому, что
 *  два-три бойца вне отрядов держались при нём по-прежней логике: у D5 было шесть-семь наших. Что должно быть верно, чтобы
 *  план выигрывал: D5 держат шесть-семь тел, и ещё две четвёрки стоят на H — это пятнадцать бойцов при наших двенадцати;
 *  меньше — 9–11 очков против его 14–16. Выключено; код оставлен для сочетаний.
 *  Снова включено в v613 — как основа налётчика (USE_RAIDER): гарнизоны на обоих H, третий отряд ходит. */
internal const val USE_CAMP_BREAK = true

/** РАННИЙ СТАРТ ПЛАНА (v606, см. USE_CAMP_BREAK). Живой блок v605 — 0-8, но то, ради чего план, сработало: в трёх руках,
 *  где лагерь сложился, он уступил D5 натиску, и гарнизоны на D5 и H простояли до конца матча без единой потери с обеих
 *  сторон (тела 11:12 и 8:11 с натиска до финала, 500–700 тиков). Провалы — время и число: лагерь складывался поздно
 *  (t=660–970) или не складывался вовсе (пять рук из восьми — наша армия, играя по-старому, не даёт ему встать), к t=400 он
 *  забирал флаги 1:6 в шести руках, хотя на t=200 мы вели во всех восьми, а к натиску у нас было 11 или 8 бойцов — два
 *  отряда вместо трёх, 9 очков против 16. Что должно быть верно: план стартует, пока нас двенадцать и мы ведём, — когда
 *  его дебютный бросок к оспариваемому флагу успел дойти и схлынуть (двойной путь от его базы); лагерь, сложившийся
 *  раньше, запускает план тоже.
 *  ➖ ЗАМЕР v606 (0-8): план шёл до конца во всех восьми, счёт ближе (лучшие 17 848 : 22 425, 15 912 : 23 341), но четвёрка
 *  на D5 гибла во всех восьми (t=132–324, его 9–12), и до конца держались два флага из трёх. Разбор v600–v606 назвал
 *  правило: устоявшийся гарнизон гибнет ТОЛЬКО когда у него 0–2 флага (15 гибелей: при 0 — 10, при 1 — 3, при 2 — 2), при
 *  трёх и больше — ни одной на 29 113 выборках стояния, при любом нашем числе. Ранний старт отнимал у него флаги ниже порога.
 *  Выключено в v607 — см. USE_PASSIVE_GATE; снова включено в v609: «покой при трёх его флагах» не подтвердился, а ранний
 *  старт — единственный способ дойти до плана всеми двенадцатью (см. USE_LEAVE_WHEN_CLEAR). */
internal const val USE_EARLY_CAMP_BREAK = true

/** ВОРОТА ЕГО ПОКОЯ (v607, см. USE_CAMP_BREAK). Разбор реплеев v600–v606 (гарнизонов, простоявших на флаге 20+ тиков, 3+ своих
 *  рядом): гибель — только при его 0–2 флагах (15 из 15), при его 3+ — 0 на 29 113 выборках (его 3 — 513, 4 — 1 744, 5 —
 *  23 925, 6 — 2 897), и это правило ЕГО числа, не нашего: при его 0 и наших 4–7 — 0 гибелей на 613 выборках. Он идёт
 *  отбивать, пока у него меньше трёх; с тремя и больше стоит. (Ранние тики с его малым числом совпадают — правило может быть
 *  и временным; живой замер различит.) Что должно быть верно, чтобы три наших гарнизона стояли до конца: у него всё время
 *  не меньше PASSIVE_FLAGS. Поэтому план стартует, когда у него флагов не меньше PASSIVE_FLAGS плюс флаги плана, которые
 *  сейчас его; цель плана — D5 и оба H (13 очков против его 12 на A и R — ему остаётся четыре); скауты с начала плана его
 *  флаг не берут, если у него их не больше PASSIVE_FLAGS.
 *  ➖ ЗАМЕР v607 (0-8): ворота работают — там, где план развернул отряды, гарнизоны на D5 и H стояли с t≈380 до конца матча
 *  без единой потери (армия 11 против его 14 все 1 200 тиков). Но к старту плана у нас 10–11 бойцов — отрядов по четыре два,
 *  и мы держим 9 очков против его 16 при счёте на t=400 около равного (например, 2 681 : 1 930 — с 13 против 12 с t=400 к
 *  t=2000 было бы ~23 500 : 21 100). v608: при воротах покоя отряд может быть тройкой — бойцов на отряд GARRISON_SIZE − 1,
 *  не больше трёх отрядов (9–12 бойцов — три отряда, 8 — два). Цена: стоящую тройку в v602 он бил, но тогда у него было 0–2
 *  флага; при его покое тройки не мерены.
 *  ⚠️ ОТВЕРГНУТО ЖИВЫМ ЗАМЕРОМ (v609, 23.09.2026): блок v608 — 0-8, три отряда развёрнуты во всех восьми, но «покой при
 *  трёх его флагах» не держится: гарнизоны гибли при его 4–5 флагах. Тройки на H гибли (две руки с 10 бойцами — оба
 *  H-отряда, как в v602), четвёрка на D5 — в четырёх руках сразу после ухода восьмёрки, когда у D5 стояли его 7–12 (в v607
 *  она выжила там, где при уходе рядом было трое). Правило «гибель только при его 0–2 флагах» — совпадение с ранними тиками;
 *  причина — уход от гарнизона при его армии рядом. С v609 — ранний старт (USE_EARLY_CAMP_BREAK), только четвёрки и уход
 *  по USE_LEAVE_WHEN_CLEAR.
 *  Снова включено в v611 — как ВОРОТА СТАРТА (тройки отвязаны в USE_PASSIVE_TRIPLES): ранний старт v609–v610 держал D5 с
 *  дебюта, и лагерь не складывался, а четвёрка на D5 гибла, как только от двенадцати оставалось четыре; поздний старт v607
 *  сбивал его сложившийся лагерь, и после этого четвёрка на D5 стояла до конца в шести руках из восьми.
 *  Выключено в v613 (USE_RAIDER): гарнизона на D5 нет, лагерь сбивать незачем — ранний старт v609 (USE_EARLY_CAMP_BREAK), при
 *  котором к t≈230 все три отряда были на местах и на t=400 мы вели в шести руках из восьми.
 *  Снова включено в v614: без отряда D5 при раннем старте его голод (0–1 флаг) утоляла первая H-четвёрка — шесть рук v613
 *  из восьми (см. USE_RAIDER).
 *  ⚠️ ОТВЕРГНУТО ЖИВЫМ ЗАМЕРОМ (v615, 23.09.2026): блок v614 — 0-8. Первая H-четвёрка гибла во всех восьми (t=317–715) при его
 *  5–6 флагах — «сытый не нападает» неверно; а план, начатый при его 3+ флагах, отдал дебют: на t=300 темп 4:21 в пяти руках
 *  (в v613 на t=300 мы вели в семи из восьми). Выключено: старт ранний (USE_EARLY_CAMP_BREAK). */
internal const val USE_PASSIVE_GATE = false

/** Тройки при воротах покоя (v608) — выключены с v611: v602 и v608 — стоящие тройки он бьёт при любом своём числе флагов. */
internal const val USE_PASSIVE_TRIPLES = false

/** АРМИЯ БЕЗ ОДИНОЧЕК С ПЕРВОГО ТИКА (v611, `Signals.lonerHunted` под USE_CAMP_BREAK). Живые блоки v607–v608: к старту плана у
 *  нас 10–11 бойцов, а не двенадцать, — терялись одиночки-бегуны у дальних флагов (v608: мили у (93,26), (93,16), (75,9),
 *  стрелок у (15,62), «наших в 6» — ноль), и отрядов по четыре выходило два: 9 очков против 16. Что должно быть верно, чтобы
 *  к плану дошли все: до него никто не выходит из армии поодиночке — тот же запрет, что после его первой охоты (v579–v581),
 *  но с первого тика. */
internal const val USE_BLOB_UNTIL_PLAN = true

/** УХОД ОТ ГАРНИЗОНА — КОГДА ЕГО ГРУППЫ НЕТ РЯДОМ (v609, `Garrisons.campBreak`, функция `clear`). Живые блоки v606 и v608:
 *  четвёрка на D5 гибла сразу после ухода восьмёрки к H (v606 — все восемь рук на t=132–324; v608 — четыре руки, у D5 его
 *  7–12), а там, где при уходе его рядом было трое, стояла до конца (v607). Что должно быть верно, чтобы устоявшийся
 *  гарнизон пережил уход своих: в момент ухода его группы (боевой и GARRISON_SIZE − 1 его в MASS_RANGE) нет в
 *  2 × BAIT_STANDOFF клетках от флага. Отряды ждут у флага, пока так не станет; цель плана — D5 и оба H.
 *  ➖ ЗАМЕР v609 (0-8): план шёл быстро и целиком — к t≈230 три четвёрки на D5, Ha и Hb, H-гарнизоны стояли до конца без
 *  потерь, на t=400 мы вели в шести руках из восьми (до 5 215 : 1 251); но четвёрку на D5 он выбивал на t=154–341, уже
 *  устоявшуюся, и дальше 8 очков против 17. В v607 (поздний старт, у него 5+ флагов) та же четвёрка на D5 после ухода
 *  восьмёрки стояла до конца в шести руках из восьми. v610 — см. USE_HOLD_UNTIL_PASSIVE. */
internal const val USE_LEAVE_WHEN_CLEAR = true

/** D5 ДЕРЖИТ ВСЯ АРМИЯ, ПОКА ОН НЕ УСПОКОИТСЯ (v610, `Garrisons.campBreak`, функция `passive`). Сочетание того, что сработало:
 *  ранний натиск (v606, v609) даёт D5 с дебюта и всех двенадцать, а стоящую группу из двенадцати он не трогает; поздняя
 *  раскладка (v607) — четвёрка на D5 переживает уход своих, когда у него пять флагов и больше. Поэтому армия стоит на D5
 *  всей массой, пока у него не станет PASSIVE_FLAGS плюс ещё не наши флаги плана (оба H — пять), и только тогда восьмёрка
 *  уходит сажать H-гарнизоны — и уходит, когда его группы нет рядом (USE_LEAVE_WHEN_CLEAR).
 *  ➖ ЗАМЕР v610 (0-8): четвёрка на D5 гибла вскоре после ухода восьмёрки во всех восьми (его 8–12 у D5 на этапах 4–5), H-
 *  гарнизоны стояли до конца — 8 против 17. Пока D5 держали двенадцать, его лагерь не складывался, и он оставался
 *  деятельным; в v607, где натиск сбивал его сложившийся лагерь, та же четвёрка стояла. С v611 план стартует по воротам
 *  покоя (USE_PASSIVE_GATE); это условие остаётся — оно уже выполнено к старту.
 *  Выключено в v613 вместе с USE_PASSIVE_GATE: условие держало армию у D5, а гарнизона на D5 больше нет. Снова включено в
 *  v614 вместе с ним: восьмёрка уходит от H-четвёрки, когда у него флагов не меньше PASSIVE_FLAGS плюс ещё не наши H.
 *  Выключено в v615 вместе с ним (блок v614 — 0-8, см. USE_PASSIVE_GATE). */
internal const val USE_HOLD_UNTIL_PASSIVE = false

/** ЗАСАДА У УГЛА (v615, `Garrisons.campBreak`, этапы 7 — засада и 8 — удар; прибор `camp=strike`).
 *
 *  Блоки v613–v614: первую H-четвёрку он выбивал в 14 руках из 16 — всей армией (его 9–12 в 6 клетках), через 60–80 тиков
 *  после ухода восьмёрки, начиная сближение, когда наши вне гарнизона отходили на 30–46 клеток, а его армия была ближе к
 *  гарнизону, чем они (его 21–27 против наших 41–46). У него в эти моменты 5–6 флагов: атака и дальний удар ×0,6, лечение
 *  ×0,75, уязвимость ×1,1; у нас один H. Это приманка, которую он берёт — в отличие от приманок v587–v599 — и берёт в углу
 *  карты, откуда выход один: мимо того, кто придёт следом.
 *
 *  Что должно быть верно, чтобы четвёрка в углу стала ловушкой, а не жертвой: восьмёрка рядом, но вне его счёта, и
 *  возвращается, как только он пошёл. Поэтому после посадки первого гарнизона восьмёрка идёт к второму флагу только на
 *  LURK_DIST шагов и стоит; его вооружённая группа ближе 2 × BAIT_STANDOFF к гарнизону и ближе к нему, чем наши, —
 *  восьмёрка идёт к гарнизону, бой ведут обычные ветки огня; его группы нет рядом GARRISON_SETTLE тиков — план идёт дальше.
 *  Не пришёл за LURK_TICKS — тоже дальше.
 *  ⚠️ ОТВЕРГНУТО ЖИВЫМ ЗАМЕРОМ (v616, 23.09.2026): блок v615 — 0-8, армия 7–8 к t=600 во всех восьми. Удар срабатывал в пяти
 *  руках (этап 8 — 49–76 тиков), но он уходил, едва восьмёрка поворачивала (его правило «от натиска — прочь»), выжидал, пока
 *  она снова пойдёт ко второму флагу, и выбивал четвёрку, когда наши были в 36–80 клетках (6ab3eec6: t=367–380, наши в
 *  75–80). Стоящий гарнизон в углу он дожидается всегда; засада только откладывает. Что должно быть верно, чтобы четвёрка
 *  не гибла: она не стоит там, откуда ей некуда уйти, — см. USE_ALL_RAIDERS. */
internal const val USE_CORNER_STRIKE = false

/** ВСЕ ОТРЯДЫ — НАЛЁТЧИКИ (v616, `Garrisons.raidAll`; прибор `raid=` — go / refuge / away / hold по отрядо-тикам).
 *
 *  Блоки v613–v615 (24 руки, 1 победа): налётчик v613 за 24 руки погиб дважды, а стоящие четвёрки на H — в 20 руках из 24,
 *  всегда одинаково: его армия выжидала, пока наша восьмёрка отойдёт на 30+ клеток, и выбивала четвёрку в углу, откуда выхода
 *  нет. Его собственные малые группы мы не ловим по той же причине: они держатся в 5–7 клетках от нашей группы и уходят той
 *  же скоростью. Там, где четвёрки выжили, налётчик держал 11 против 14.
 *
 *  Что должно быть верно, чтобы наши флаги держались, а четвёрки жили: ни одна четвёрка не ждёт его на месте. Поэтому
 *  посадок нет — армия с начала плана делится на три отряда по GARRISON_SIZE, и каждый — налётчик (USE_RAIDER): свой
 *  ближний не наш флаг без его группы у флага и на пути; его группа ближе RAID_DANGER — отряд уходит к своему отряду, к
 *  которому мы ближе, чем он (восемь он не атакует), и возвращается к налётам, когда её нет в RAID_DANGER + FIST_RADIUS.
 *  Одна его армия против трёх отрядов той же скорости: флаги, от которых она далеко, — наши. */
internal const val USE_ALL_RAIDERS = true

/** Засада — столько шагов от первого гарнизона по пути ко второму флагу: сближение он начинал, когда наши вне гарнизона
 *  были в 30–46 клетках (блоки v613–v614), — ближняя граница, дальше подмога опаздывает к четвёрке, которая держится 8–40
 *  тиков. */
internal const val LURK_DIST = 30

/** Засада ждёт столько тиков: все 14 нападений блоков v613–v614 пришли через 60–80 тиков после ухода восьмёрки. */
internal const val LURK_TICKS = 150

/** НАЛЁТЧИК (v613, `Garrisons.raid`, третья цель плана USE_CAMP_BREAK; прибор `raid=`).
 *
 *  Разбор 16 рук v610–v611 (реплеи обеих сторон): в 12 из них с t≈500–700 до конца матча всё ЗАМИРАЕТ — наши четвёрки на Ha и
 *  Hb, его 7–9 вооружённых квадратом 3×3 на D5, три его лекаря и скауты в 7–8 клетках от одной нашей четвёрки и в 31–46 от
 *  своих; выстрелов нет 1 000+ тиков, флаги 8 против 17. Его флаги Aa, Ab, Ra, Rb (12 очков в тик) не охраняет никто: флаги ему
 *  приносит армия (2 312 захватов вооружёнными из 2 496 на 169 играх, скаутами — 46), а армия стоит на D5 (от неё до Aa и
 *  Ab 17–19 клеток, до Ra и Rb — 36). Четвёрка, которая в v605–v611 гибла на D5, в замершей фазе ничем не занята.
 *
 *  Что должно быть верно, чтобы его флаги стали нашими: кто-то ходит по ним, пока его армия далеко, и уходит к своим, когда
 *  она идёт. Поэтому гарнизоны — на двух самых дорогих флагах вне его лагеря (оба H, 8 очков — их он не трогает), а третий
 *  отряд после посадки обоих — налётчик: берёт ближний не наш флаг, у которого нет его вооружённой группы в RAID_DANGER; его
 *  группа у налётчика — налётчик уходит к ближнему гарнизону (восемь он не атакует) и ждёт, пока её не станет в
 *  RAID_DANGER + FIST_RADIUS. Одна армия не охраняет пять флагов по разным краям карты против налётчика той же скорости.
 *  ➕ ЗАМЕР v613 (1-8, первая победа над ним с v586): в двух руках, где армия цела, с t≈600 до конца 11 против 14 (Ha, Hb и
 *  Rb у нас) — 23 139 : 18 803 и 20 926 : 21 508. В шести — ПЕРВУЮ H-четвёрку на t=210–380 у флага выбивали его 11–12 вскоре
 *  после ухода восьмёрки, при его 0–1 флагах (раннего старта v609 держал в сытости отряд D5, которого теперь нет), дальше 7–9
 *  против 16–18. Налётчик ходил маятником: флаг цели был чист, а путь к нему шёл мимо его пятерых (go и refuge поровну,
 *  по ~50 тиков на сотню). v614: ворота покоя на старте и на уходе (USE_PASSIVE_GATE, USE_HOLD_UNTIL_PASSIVE) и путь без
 *  него (RAID_ROUTE). */
internal const val USE_RAIDER = true

/** ПУТЬ НАЛЁТЧИКА БЕЗ НЕГО (v614, см. USE_RAIDER): флаг — цель, только если на всём спуске по полю от налётчика до флага нет
 *  его вооружённой группы в RAID_DANGER. */
internal const val RAID_ROUTE = true

/** Его группа ближе этого к налётчику — налётчик уходит к своим; флаг с его группой ближе этого — не цель. Он начинает
 *  нападение с BAIT_STANDOFF (его кусок в 12–14 клетках в начале нападений, разбор 81 реплея), и налётчику нужно заметить его
 *  раньше: запас — три тика хода. */
internal const val RAID_DANGER = BAIT_STANDOFF + 3

/** УХОД ОТ ГАРНИЗОНА СЧИТАЕТ ТОЛЬКО ВООРУЖЁННЫХ (v613, функция `clear` в `Garrisons.campBreak`). Разбор v610–v611: его три
 *  лекаря ходят тенью в 7–8 клетках от нашей группы (38 626 выборок: одинокий безоружный отходит прямо от нашего ближайшего
 *  вооружённого, среднее косинуса 0,61) — и держали `clear` ложным до конца матча в четырёх руках v611, где армия так и
 *  простояла у D5. Лекарь не бьёт: уход от гарнизона ему не опасен. */
internal const val USE_CLEAR_BY_ARMED = true

/** Его флагов, с которых устоявшиеся гарнизоны он не трогает (разбор v600–v606: гибели при 0–2, ни одной при 3+). */
internal const val PASSIVE_FLAGS = 3

/** Его лагерь — столько его боевых у оспариваемого флага: двойной гарнизон (в разобранных руках лагерь — девять). */
internal const val CAMP_MIN = 2 * GARRISON_SIZE

/** ...и столько тиков подряд: два окна по 10 тиков — та же мера «стоит», которой он сам различает стоящую группу. */
internal const val CAMP_TICKS = 20

/** Отряд устаивается столько тиков, пока остальные стоят рядом: его «стояла оба окна по 10 тиков» (разбор 81 реплея:
 *  нападения на группы, вставшие 3–18 тиков назад, — 5 из 6 нападений на стоявшие). */
internal const val GARRISON_SETTLE = 20

/** УКЛОНЯЮЩИЕСЯ ОТРЯЖЁННЫЕ (v594, `ScoutEvade.evadeArmed`, ветка EVADE вооружённого бегуна).
 *
 *  Асимметрия, которая решает гонку флагов против けろびー#22: он держит много флагов, потому что его одиночек мы не ловим
 *  (они держатся в 5–7 клетках от нашей группы), а мы не держим, потому что наших одиночек он ловит — четверо подходят с
 *  18 клеток и добивают за 9 тиков, стреляя на ходу (разбор 13 реплеев), пока наш стоит на флаге или бежит прочь к краю.
 *  Запрет одиночек (v579–v581) сберёг тела, но отдал ему флаги: одна наша группа держит один-два.
 *
 *  Что должно быть верно, чтобы наш одиночка жил, как его: уходить, пока путь к своим открыт, а не когда охотники уже в
 *  дальности. Та же мера, что у скаута (v576), с ценой хода самого крипа (вооружённое тело в болоте впятеро медленнее):
 *  бегун идёт на свой флаг, если приходит туда с запасом раньше его выстрела; стоит на своём, пока запас есть; когда его
 *  выстрел по клетке бегуна ближе двойного пути по области к центру армии — идёт к своим. Запрет одиночек снят на замер.
 *  Новых чисел нет. Прибор `rev=`. */
internal const val USE_EVASIVE_RUNNERS = false
// ⚠️ ОТВЕРГНУТО ЖИВЫМ ЗАМЕРОМ (v595, 23.09.2026): первая рука v594 (6ab33902) — десять одиночных смертей (хранители 5,
// бегуны 4, вдали 2) против 0–3 после признака у v581–v584, тела 9 -> 4 к t=1000, флаги 0:7 с t=800. Бегуны гибли на пути
// к флагу (t=746, 1050), а хранители — главный источник одиночных смертей — уклонением не покрыты вовсе: они в конвейере
// тактика. Что должно быть верно: уклоняется КАЖДЫЙ одиночка, включая хранителя, — отдельная работа в `updateKeepers` и
// ветке хранителя тактика; без неё снятие запрета одиночек только возвращает ему добычу.
// ⚠️ ОТВЕРГНУТО ЖИВЫМ ЗАМЕРОМ (v586, 23.09.2026): блок v585 — 0-10, скауты гибли РАНЬШЕ (в четырёх руках t=107–133 против
// 216–646 у v584), и снова в углу у нашей базы: из угла путь к армии уже отрезан, ветка `home` не включается. Что должно
// быть верно: путь к своим открыт в момент, когда он подходит, — а приманка уводит скаута туда, где его нет.
// ⚠️ ОТВЕРГНУТО ЖИВЫМ ЗАМЕРОМ (v583, 23.09.2026): две руки v582 — натиск держался 678 и 723 тика, и ни одного флага. Во
// второй (6ab31a00) тела 10:10 с t=400 до t=800, два его лекаря убиты, на t=400 мы ведём 4 466 : 900 — а флаги 1:6 с t=600
// до конца: он от натиска уходит (разбор: 86 %), армия идёт за ним, а его шесть флагов остаются его. Что должно быть
// верно: сильнейший забирает ФЛАГИ, а не гонится за тем, кто от него уходит, — см. USE_CONTESTED_FLAG_LAST.

/** СКАУТ ИДЁТ К ПРОСТОРУ, А НЕ В ДАЛЬНИЙ УГОЛ (v596, `ScoutEvade.openStep`, ветки `scev=` open / room / stay / cornered).
 *
 *  Разбор 62 игр v576–v594 против けろびー#22 (субагент Opus, 23.09.2026): погибли все 124 скаута, 118 — в тупике у края
 *  карты; сближение его вооружённых со скаутом в угловом кармане кончалось гибелью 98 раз из 98, вне углов — 17 из 82.
 *  Окружать он не умеет: у 116 гибелей из 124 его вооружённые подходили с одной стороны (дуга меньше 90°). В угол скаута вела
 *  наша же цель `hide` — «клетка области, которую он обстреляет позже всех», это и есть дальний угол, — и там он стоял
 *  (`stay` — последняя ветка у 97), пока выхода не осталось. Пока скаут жив, мы набираем 12,9–15,3 очка в тик против его
 *  4,4–6,1 (оба мертвы — 7 против 8,5–15,9); при гибели последнего скаута мы впереди в 61 игре из 62, в конце — позади в 60.
 *
 *  Что должно быть верно, чтобы скаута не загнали: он избегает тупика ЗАРАНЕЕ, пока выход открыт. Мера тупика — сама
 *  область скаута (клетки, куда он приходит раньше выстрела): в кармане она сжимается до кармана. Поэтому скаут каждый тик
 *  делает шаг, после которого его область больше; пока она не меньше SCOUT_OPEN_CELLS, места хватает, и он стоит. Флаг
 *  скаут берёт, только если успевает на него с запасом и в момент прихода область с флага не меньше SCOUT_OPEN_CELLS, —
 *  за флагом в карман он не уходит. Прибор `scev=`.
 *  ⚠️ ОТВЕРГНУТО ЖИВЫМ ЗАМЕРОМ (v597, 23.09.2026): блок v596 — 0-6. Скауты гибли там же и тогда же — у края и в углах
 *  ((97,4), (1,97), (95,97), (1,1), (97,94), (94,55)), первый на t=62–200, второй на t=86–462 (v576–v594: медианы 228 и 280),
 *  а ранний D5 пропал: его первый флаг — D5 на t=38 в пяти руках из шести (в v576 — t=126–278), потому что D5, куда идёт и
 *  он, порога области не проходит. След 6ab37e7c: скаут с t=20 шагал по `room` и на t=160 сам вошёл в угол (97,94);
 *  второй взял Ab, пересёк карту поверху и шагом `room` ушёл к краю (94,55). Жадный шаг к большей области не спасает от
 *  широкого фронта: его пятёрка идёт с одной стороны, и большая область всегда ПОЗАДИ скаута — у края; равный по скорости
 *  беглец от фронта шире своей дальности на ограниченной карте упирается в край. Что должно быть верно, чтобы скаут жил:
 *  выход — не прочь от фронта, а МИМО него (кольцо вокруг стены, чей обход длиннее его фронта), либо фронт распадается.
 *  С v597 цель снова та, что в v576. */
internal const val USE_SCOUT_OPEN_EVADE = false

/** Запас шага скаута (тики): одна его заявка на ход за тик может не пройти (толкотня), и тогда он стоит лишний тик. */
internal const val SCOUT_STEP_MARGIN = 1

/** Область, при которой места скауту хватает (клеток; см. USE_SCOUT_OPEN_EVADE). Замер той же выборки (180 сближений его
