/** ЛЕКАРЬ ЦЕНИТ КЛЕТКУ ПО ЛЕЧЕНИЮ, КОТОРОЕ ДОСТАВИТ ТОМУ, КТО РЕАЛЬНО ТЕРЯЕТ ХИТЫ (v435, см. scoreHeal, stampHealNeed).
 *  Правило арены: HEAL даёт 12 хитов на часть вплотную и 4 на дистанции ≤ 3 — h6: 72 против 24. Нужда прежде бралась
 *  потенциалом (опасность поля E в клетке подопечного), и притяжение насыщалось у ЛЮБОГО бойца с нуждой от 72, то есть
 *  второй ряд читался как первый; насыщенная сумма при нужде в сотни у пятерых бойцов плоская, и лекаря держит
 *  влияние линии. Зонд hpick в 23 играх против Coldkimchi#1: разница притяжения «выбранная минус клетка вплотную к
 *  бойцу под огнём» 0–4, влияния −4…−69 в пользу выбранной; лекарей вплотную 15–25 %. Разбор 46 ранних поражений
 *  (Opus): у нас 26 % лечений вплотную против его 75 %, одно лечение 35,8 хита против 60,1, наше лечение 6 612 против
 *  его 10 161 при равном числе лечений; порядок доказан временем (прилегание расходится в t+0…20, раны — в t+40…80).
 *  Теперь нужда = недобор хитов + потеря за прошлый тик (то, что лечение может вернуть), а цена клетки — лучшая ОДНА
 *  доставка min(нужда, лечение × ядро по дистанции): вплотную к бьющемуся 72, в двух-трёх клетках 24, у целого — 0.
 *  Опасность клетки и экран не тронуты: под его пятью стволами клетка по-прежнему стоит 300. */
internal const val USE_HEAL_NEED_ACTUAL = true

/** ЛЕКАРИ ПОД ПРИКАЗОМ КОМАНДИРА ВО ВСЯКОМ КОНТАКТЕ (v436, см. armyCommand, commandFight healersOnly). Режим боя
