 *  на любой контакт» ронял roost и scatter; и приказ «стоять» лекарю исполняется как приказ. Прибор `cmdheal=`. */
internal const val USE_COMMANDER_HEALERS_IN_CONTACT = true

/** ЦЕНА КЛЕТКИ ЛЕКАРЯ БЕЗ ВЛИЯНИЯ ЛИНИИ (v437, см. scoreHeal). Доставка, огонь и экран — в хитах, влияние (наши − его
 *  поля) безразмерно и в арене ничем не обосновано для лекаря. Зонд dh «выбранная минус безопасная клетка вплотную к
 *  бойцу под огнём» в v434/v435/v436: влияние −19,7 / −8,0 / −28…−38 в пользу выбранной при доставке +0,0 / +4,8 /
