/** ДОСТАВКА В ЦЕНЕ КЛЕТКИ ЛЕКАРЯ — ТОЛЬКО ПОДОПЕЧНЫМ В ЗОНЕ ОГНЯ (v438, см. bestDeliveryAt). Хиты — запас, лечение —
