 *  достаёт, лечение ОТЛОЖИМО — те же 72 вернут те же 0,72 части и через десять тиков; подопечному под N стволами оно
 *  СКОРОПОРТЯЩЕЕСЯ — не доставленное сейчас становится снятой частью (30 урона у мили, 10 у стрелка, 12 лечения у
 *  лекаря). Цена «лучшая одна доставка» платила за оба случая ровно 72 и не отличала их — та же плоскость, что K[2] =
