 *  (у него 33,8 %), недобор нашей цели 279 против его 82, лекарь вплотную к бойцу в зоне огня в 11,4 % лекаре-тиков
 *  против его 43,8 %; клетка на d = 2 стоит нашему лекарю нетто +78 в тик, на d = 3 +101. Зона огня — поле eFire (его
 *  мили вплотную, стрелок в ≤ 3, без шага сближения). Режим решается на лекаря за тик: есть терявший подопечный в зоне
 *  огня в досягаемости шага (d ≤ 5) — доставка считается по одним таким; иначе по-старому (иначе поле снова ноль везде
 *  и лекарей ничто не держит при армии — match29:camp у первой редакции v437). Прибор `hfire=` — доля лекарей в режиме.
