 *  2 208 : 961): экран тел делает огонь лекарю почти бесплатным (0,7·огонь − 0,33·огонь при PRESS), 72 доставки покупали
 *  клетку под двумя стволами, а его стрелок бьёт лекаря в досягаемости первым — hparts 18 → 0 к t=110. Принято: в режиме
 *  огня доставка есть только из клеток ВНЕ его огня (сзади подопечного) — их и не хватало в 63 % тиков по разбору. */
