 *  защёлкивается, режим пар оставляет в ядре двоих и отряжает семерых из двенадцати на гарнизон и пары при его целом блоке
 *  в пяти клетках; пятеро уходят в отход, блок возвращается и берёт флаги. Это та же L-форма, что закрыта у ворот захвата
