 *  бой, который СЛУЧИТСЯ; у Coldkimchi#1 «не бьёт» — пауза между боями. Различитель тот же — fightMassedSeen и не спит:
 *  けろびー и фермеры сомкнутыми не дерутся и режим пар против них не меняется. */
