/** У ПОДОПЕЧНОГО В ЗОНЕ ОГНЯ — ЯДРО НАСТОЯЩЕЙ ДОСТАВКИ, БЕЗ ШАГОВОЙ СКИДКИ (v439, см. bestDeliveryAt). Разбор v438 (Opus,
 *  16 реплеев против Coldkimchi#1, 8-8): режим огня v438 сменил, КОГО лечим (цель в зоне огня 36,1 → 44,1 %, недобор 279 →
