 *  огня 11,4 → 11,3 % против его 43,8 %, лечений вплотную за бой 58,4 → 49,2 % (падение внутри каждой группы), доставка
 *  32,8 → 28,4. Первый размен решает ёмкость лечения на бойце под огнём: входящее 96 против 98, ёмкость 59 против 102,
 *  без лекаря вплотную 75,0 % наших бойцов под огнём против его 21,5 %. Причина в цене: `K_HEAL_STEP[2] = γ = 0,7` даёт
 *  клетке в двух 50 при настоящей доставке 24, и последний шаг стоит 22 вместо 48 — вдвое дешевле там, где лечение
 *  скоропортящееся. Лекарь стоит в d = 2 от бойца под огнём в 3 446 лекаре-тиках (17,8 %), свободная клетка вплотную есть в
 *  79,9 %, вне его огня — в 73,3 %, шаг делается в 40,1 %; непойденных безопасных прилеганий 76 за игру × 48 хитов = 36
 *  частей оружия при 227 теряемых (16 %). В режиме огня ядро — K_ATT_HEAL (72 / 24 / 24 по дальности, 17 на d = 4 как
 *  подход); вне огня шаговое ядро остаётся — лечение отложимо, и look-ahead по нему верен. Запрет клеток под огнём (v438)
 *  не тронут: он отнимает клетки с 1,28 ствола = 77 входящих против 48 приобретаемых.
 *  ⚠️ Два сужения по гейту match20:brawl+heals (его мили-натиск с лекарями; v436–v438 уничтожали его армию на t=245–391):
 *  первая редакция — 14 632 : 15 192 по очкам, вторая (без доставки из клеток в шаге его мили, поле eMelee) — аннигиляция
 *  на t=783: к t=100 его лекари раздеты (4/18) и мощь 797 против 549, за t=100…140 наши HEAL 18 → 1 и армия 12 → 1. Точная
 *  цена «этот тик» верна против неподвижной угрозы — стрелок держит три и стоит; мили ходит клетку в тик и бьёт лекаря
 *  первым на 240, а у лекаря в режиме нет ни клея, ни штрафа за мили в двух (поле огня — радиус 1). Принято: подопечный в
 *  режиме — тот, кого достаёт его СТРЕЛОК (eRanged, ≤ 3); боец под одним мили лечится по старому правилу с look-ahead.
 *  ⚠️ ОТВЕРГНУТО ЗАМЕРОМ (v440): v439 против Coldkimchi#1 — 3-13 (19 %) при 8-8 у v438 и 14-18 у v437. Во всех 13 поражениях
 *  его лекари целы (18/18), с наших HEAL снято 3 852–8 558 хитов за игру (v438: 640–6 415), обвалы на t=430–630. Лекарь,
 *  стоящий ровно вплотную к бойцу под стрелками, раздевается первым, как только геометрия сдвигается на клетку; цена «этот
 *  тик» без предсказания его шага (Forecast.threatAt по плану переработки) не окупает 48 хитов последнего шага. Выключено:
 *  зона огня, клетки и подопечные — как у v438; сужения v439 живут под этим же тумблером.
 *  ⚠️ ОТКАЗ ПЕРЕОТКРЫТ ПОСЛЕ v497 (20.09.2026, мысль оператора). Отказ v440 мерился на боте, у которого лечение
 *  уходило в уже безоружных (38-52 %) и армия разоружалась за тридцать тиков, — то есть точность цены лекаря
 *  решалась там, где сам выбор пациента был неверен. С v497 выбор исправлен, и правило действует на населении в
 *  52 % лекаре-тиков (прибор `hstill=23129/44502` по 140 сценариям), то есть его экспозиция не под вопросом.
 *  ⚠️ И ОТВЕРГНУТО В ТРЕТИЙ РАЗ (v499). Гейт чист, экспозиция подтверждена, но живой A/B 10+10 против MetalicaX#17
 *  дал 2-8 против 3-7 у базы v497 — разницы нет. Правило не становится верным оттого, что стало применимым:
 *  цена «ровно этот тик» по-прежнему не окупает последний шаг к бойцу под огнём, и починка выбора пациента этого
 *  не меняет. Выключено окончательно; предмет закрыт тремя независимыми замерами (v440, v478, v499). */
internal const val USE_HEAL_EXACT_IN_FIRE = false

/** ЦЕНА КЛЕТКИ ЛЕКАРЯ В РЕЖИМЕ ОГНЯ ЗНАЕТ ОГОНЬ СЛЕДУЮЩЕГО ТИКА (v478, вопрос 7 оператора; см. Forecast.predictCells / Threat,
 *  InfluenceMap.HealNeed.next, Deal.scoreHeal). Итог v439 (четыре редакции точной цены упали на гейте) назван там же: цена
 *  «ровно этот тик» верна, пока угроза следующего тика равна нынешней, — а мили ходит клетку в тик и бьёт лекаря первым на
 *  240, наступающий стрелок через тик стреляет с трёх туда, где сейчас безопасно, и «безопасная клетка вплотную» живёт один
 *  тик; закрыть ёмкость лечения на бойце под огнём (59 против его 102 по разбору v438) надо ценой клетки, которая знает огонь
 *  СЛЕДУЮЩЕГО тика. Здесь, только у лекаря и только в режиме огня (USE_HEAL_DELIVERY_IN_FIRE): (1) зона огня подопечного — его
 *  стволы ПОСЛЕ шага по модели проката (стрелок ≤ 3, мили ≤ 1 от предсказанной клетки), а не поля eFire / eRangedStill этого
 *  тика; (2) доставки нет из клетки, где хоть один его ствол после шага возьмёт лекаря целью (адресно, «лекарь первым» — та
 *  же модель, что у wallTargetOf, 85–97 % совпадений), вместо запретов eFire-сейчас и eMelee-шаг; (3) слагаемое опасности —
 *  та же адресная угроза t+1 вместо fireFieldAt, и экран тел лекарю не скидка (его стрелок бьёт лекаря, а не тела перед ним);
 *  (4) ядро доставки — настоящее (K_ATT_HEAL, как в v439), опорная клетка подопечного — НАЗНАЧЕННАЯ этой раздачей: ход лекаря
 *  окупается следующим тиком, когда подопечный уже там. Бойцов не касается: у них адресная угроза отвергнута дважды (v244
 *  заменой, v246 добавочным термом — 0-8 против кайтера, терм уводит из клетки того, кого ствол выберет целью); у лекаря этой
 *  ловушки нет — по модели он и есть цель. Оговорки v438/v439 остаются: сам лекарь режим не включает, идущий вперёд боец
 *  (advancingWards) в режим не входит. Прибор `hnext=подопечных под огнём t+1/из них не под огнём сейчас/под огнём сейчас, но
 *  не t+1` — где прогноз расходится с настоящим. Судится гейтом (FAIL-only, четыре призрачные записи отступления) и A/B. */
internal const val USE_HEAL_THREAT_NEXT = true

/** ...И ЗНАЕТ ЕГО ВСЕГДА, А НЕ ТОЛЬКО В РЕЖИМЕ ОГНЯ (v507, см. Deal.scoreHeal). Вне режима огня цена клетки лекаря
 *  берёт опасность как `fireFieldAt` — поле ЭТОГО тика, то есть досягаемость 3 от НЫНЕШНИХ его клеток. Но он тоже
 *  ходит: после его шага под огнём вся зона радиуса 4, поэтому клетка на расстоянии ровно 4 читается сегодня как
 *  совершенно безопасная и завтра оказывается под обстрелом. Это арифметика правил (дальность 3 + шаг 1), а не
 *  корреляция исходов.
 *
 *  Замер четырёх поражений от MetalicaX#17 по реплеям (21.09.2026) называет цену ошибки прямо. Входов лекаря под
 *  огонь за матч 38-61, и разложены они контрфактически: **его шаг 58-67 %**, наш шаг 4-16 %, «у него ожило оружие
 *  после лечения» и «исчез экран из своих тел» — РОВНО НОЛЬ входов на все четыре матча. В сам тик входа лекарь стоял
 *  на месте в 45-57 % случаев, лечил в 96-100 %, стоял вплотную к своему бойцу (медиана 1,0) и в двух клетках от
 *  центроида — то есть не лез вперёд. Эпизод длится 1-2 тика (медиана), и в 75-87 % лекарь выходит из-под огня
 *  СВОИМ ЖЕ шагом, то есть реагирует постфактум: опоздание ровно на тик, повторяемое весь матч.
 *
 *  Прибор правки — `hexp=` (лекарь в бою и в досягаемости его вооружённых / лекарь-тиков боя): 143/353 = 40 % в
 *  прочитанном поражении против 23/169 = 14 % в победе; по реплеям экспозиция 85/383/106/99 крип-тиков в поражениях
 *  против 14/161/20/14 в победах.
 *
 *  ⚠️ Это НЕ отвергнутая адресная опасность t+1 у БОЙЦОВ (v244 и v246, по 0-8 живьём): там прогноз ставился в
 *  опасность клетки ВСЕМ ролям и обнулял у бойцов чувство угрозы. Здесь только лекарь, и только расширение уже
 *  принятого v478 с режима огня на обычный — та же величина, тот же `threatNext`, который и так готовится для
 *  КАЖДОГО лекаря (`Deal.kt`, `threatNext.prepare`), ни одной новой константы.
 *
 *  ⚠️ ОТВЕРГНУТО ГЕЙТОМ И СВОИМ ПРИБОРОМ (v508, парный прогон 21.09.2026), И ОТКАЗ НАЗЫВАЕТ ОШИБКУ ФОРМЫ.
 *  Гейт: 142 PASS против 143, упал `match30:scatter` — 24285:18412 (победа) стало 22990:24282 (поражение); с
 *  выключенным тумблером сценарий проходит в точности как прежде. Прибор `hexp=` по 140 сценариям: 2688/22907 =
 *  11,7 % при включённом против 2641/20450 = 12,9 % при выключенном, то есть 1,2 пункта суммарно — но ПО
 *  СЦЕНАРИЯМ 26 лучше, 35 ХУЖЕ, 79 без изменений, и в пяти худших экспозиция выросла на 11-28 пунктов
 *  (`match33:nine` 28/54 против 15/62, `match31:rush` 33/75 против 14/75).
 *
 *  ⚠️ ПРИЧИНА — ПРАВКА ОПТИМИЗИРУЕТ НЕ ТУ ВЕЛИЧИНУ, ЧТО МЕРИТ ЗАМЕР. `threatNext` считает урон, АДРЕСОВАННЫЙ
 *  этому крипу: если его стрелок по модели выберет другую цель, клетка читается безопасной — хоть на дистанции 2.
 *  А реплеи (и сам `hexp=`) меряют ДОСЯГАЕМОСТЬ: «внутри радиуса вообще», независимо от того, в кого он целится.
 *  Замер входов говорит именно про досягаемость — 91 % входов приходится ровно на границу радиуса, медиана
 *  дистанции до ствола 4 на тике до входа и 3 на тике входа, а в победах медианный запас лекаря до края радиуса
 *  10/4/14/15 против 1-2 в поражениях. Значит форма, отвечающая замеру, — не адресная угроза, а РАДИУС t+1
 *  (его дальность 3 плюс шаг = 4) в избегаемых клетках лекаря; она стоит отдельной пробы и своей версии. */
internal const val USE_HEAL_THREAT_NEXT_ALWAYS = false

/** ИЗЪЯТИЕ ИЗ ГИСТЕРЕЗИСА ПОСТУРЫ — ТОЛЬКО ПОД ОГНЁМ (v479). Постура держится POSTURE_HOLD тиков, и единственное
 *  изъятие — RETREAT: «спасение не ждёт» (v181). Но условие отхода мигает вместе с целью-флагом — её отбрасывают
 *  ворота захвата (`objnone=gate:927` из 1700 тиков живого матча против ricardo18informatica2020#14), а строка
 *  `flag` стоит в таблице выше `retreat`, — и изъятие превращает постуру в пилу: FLAG выжидает положенные пять
 *  тиков, RETREAT возвращается на первом же. В том матче 1110 переходов RETREAT<->FLAG (1137 смен всего, период 5
 *  тиков): армия ходит между флагом и точкой отхода в углу карты, счёт 2350:5280. Тот же класс дефекта уже чинили
 *  в v215 («352 смены за 1700 тиков, медиана удержания ОДИН тик») — тогда записью через те же часы; изъятие его
 *  вернуло. Здесь изъятие сужается до своего смысла: спасение — это когда БЬЮТ. Что мгновенность почти всегда
 *  лишняя, говорит прибор отхода: `retr=1481/1479/6` — из 1481 тика отхода под огнём шесть. Не под огнём RETREAT
 *  ждёт POSTURE_HOLD, как любая другая постура; под огнём — в том числе от подошедшего вплотную мили, поле урона
 *  считает и его, — входит немедленно, как раньше. Прибор `pflip=смен применённой постуры/из них эпизод короче
 *  POSTURE_HOLD/входов в отход не под огнём`. Судится гейтом (FAIL-only, четыре призрачные записи отступления) и
 *  живым A/B: отход — постура длинных матчей, и стендовая её экспозиция 1,1 %. */
internal const val USE_ESCAPE_UNDER_FIRE = true

